class ToastNotification(QFrame):
    """프로그램 중앙에 플로팅으로 안내 메시지를 띄워주는 토스트 위젯"""
    def __init__(self, text, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        
        # parent가 없을 경우 독립 윈도우 플래그 설정
        if not parent:
            self.setWindowFlags(
                Qt.WindowType.FramelessWindowHint |
                Qt.WindowType.WindowStaysOnTopHint |
                Qt.WindowType.Tool
            )
            self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        
        self.setStyleSheet("""
            ToastNotification {
                background-color: #0F172A;
                border: none;
                border-radius: 8px;
            }
            QLabel {
                background: transparent;
                color: #FFFFFF;
                font-size: 13px;
                font-family: 'Malgun Gothic', sans-serif;
                font-weight: bold;
                padding: 12px 28px;
            }
        """)
        
        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        self.label = QLabel(text, self)
        self.label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(self.label)
        self.adjustSize()
        
        # 투명도 조절 효과
        from PyQt6.QtWidgets import QGraphicsOpacityEffect
        self.opacity_effect = QGraphicsOpacityEffect(self)
        self.opacity_effect.setOpacity(1.0)
        self.setGraphicsEffect(self.opacity_effect)

    def show_toast(self, parent_window=None, duration=1500):
        self.adjustSize()
        
        # 부모 윈도우 내부 또는 화면 중앙 좌표 계산
        if self.parent():
            p_rect = self.parent().rect()
            x = (p_rect.width() - self.width()) // 2
            y = (p_rect.height() - self.height()) // 2
            self.move(max(0, x), max(0, y))
        else:
            if parent_window:
                rect = parent_window.geometry()
                c = rect.center()
                self.move(c.x() - self.width() // 2, c.y() - self.height() // 2)
            else:
                screen = QApplication.primaryScreen()
                if screen:
                    c = screen.geometry().center()
                    self.move(c.x() - self.width() // 2, c.y() - self.height() // 2)

        self.show()
        self.raise_()
        
        # 대기 후 페이드아웃
        from PyQt6.QtCore import QTimer
        QTimer.singleShot(duration, self.fade_out)
        
    def fade_out(self):
        try:
            from PyQt6.QtCore import QPropertyAnimation
            self.anim = QPropertyAnimation(self.opacity_effect, b"opacity")
            self.anim.setDuration(250)
            self.anim.setStartValue(1.0)
            self.anim.setEndValue(0.0)
            self.anim.finished.connect(self.close)
            self.anim.start()
        except:
            self.close()


_active_toasts = []

def show_copy_message(text, widget=None):
    clean_text = text
    # 아이콘 및 이모지 완전 제거
    emojis = ["📋", "💾", "✨", "✏️", "🔓", "📁", "✅", "❌", "⚠️", "🧼", "🧹", "⭐", "🔗", "💡", "🖥️", "🗑️", "📝"]
    for emoji in emojis:
        clean_text = clean_text.replace(emoji, "")
    clean_text = clean_text.strip()

    # 현재 활성 윈도우(메인 윈도우 또는 활성 대화상자) 찾기
    target_win = None
    if widget and hasattr(widget, 'window'):
        try:
            target_win = widget.window()
        except:
            pass
    if not target_win:
        target_win = QApplication.activeWindow()

    if target_win and hasattr(target_win, 'status_bar') and target_win.status_bar:
        target_win.status_bar.showMessage(clean_text, 3000)

    global _active_toasts
    for t in _active_toasts:
        try:
            t.close()
        except:
            pass
    _active_toasts.clear()

    # 대상 윈도우의 직속 자식 오버레이로 생성하여 프로그램 정중앙에 100% 확실히 표시
    toast = ToastNotification(clean_text, parent=target_win)
    _active_toasts.append(toast)
    toast.show_toast(parent_window=target_win, duration=1500)


import shutil

class AttachmentListWidget(QListWidget):
    file_dropped = pyqtSignal(list)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        if event.mimeData().hasUrls():
            file_paths = []
            for url in event.mimeData().urls():
                file_path = url.toLocalFile()
                if os.path.exists(file_path):
                    file_paths.append(file_path)
            if file_paths:
                self.file_dropped.emit(file_paths)
            event.accept()
        else:
            event.ignore()


class DragDropTableListWidget(QListWidget):
    """테이블 목록에서 드래그 시 테이블명을 plain text로 전달하는 QListWidget"""
    def mimeData(self, items):
        mime_data = super().mimeData(items)
        if items:
            item = items[0]
            widget = self.itemWidget(item)
            if widget and hasattr(widget, 'table_name') and widget.table_name:
                mime_data.setText(widget.table_name)
            else:
                t_name = item.data(Qt.ItemDataRole.UserRole)
                if t_name:
                    mime_data.setText(t_name)
                else:
                    text = item.text()
                    if " (" in text:
                        text = text.split(" (")[0]
                    mime_data.setText(text.strip())
        return mime_data


class ImageResizeDialog(QDialog):
    """이미지 더블클릭 시 크기를 변경할 수 있는 다이얼로그"""
    def __init__(self, current_width, current_height, parent=None):
        super().__init__(parent)
        self.setWindowTitle("이미지 크기 조절")
        self.setFixedSize(300, 160)
        self.original_width = current_width
        self.original_height = current_height
        self.ratio = current_width / current_height if current_height > 0 else 1.0
        self.init_ui(current_width, current_height)

    def init_ui(self, w, h):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)

        form = QFormLayout()
        self.sb_width = QSpinBox()
        self.sb_width.setRange(10, 2000)
        self.sb_width.setValue(int(w))
        self.sb_width.setSuffix(" px")
        self.sb_width.setStyleSheet("padding: 3px; font-size: 12px;")

        self.sb_height = QSpinBox()
        self.sb_height.setRange(10, 2000)
        self.sb_height.setValue(int(h))
        self.sb_height.setSuffix(" px")
        self.sb_height.setStyleSheet("padding: 3px; font-size: 12px;")

        form.addRow("가로 크기:", self.sb_width)
        form.addRow("세로 크기:", self.sb_height)
        layout.addLayout(form)

        self.chk_ratio = QCheckBox("종횡비(비율) 유지")
        self.chk_ratio.setChecked(True)
        self.chk_ratio.setStyleSheet("font-size: 11px; color: #475569;")
        layout.addWidget(self.chk_ratio)

        # Signals to auto-calculate ratio
        self.sb_width.valueChanged.connect(self.on_width_changed)
        self.sb_height.valueChanged.connect(self.on_height_changed)

        # Buttons
        btn_layout = QHBoxLayout()
        btn_save = QPushButton("적용")
        btn_save.clicked.connect(self.accept)
        btn_close = QPushButton("취소")
        btn_close.clicked.connect(self.reject)

        btn_save.setStyleSheet("background-color: #2563EB; color: white; font-weight: bold; padding: 5px 12px; border-radius: 4px; font-size: 11px;")
        btn_close.setStyleSheet("background-color: #F1F5F9; color: #475569; border: 1px solid #CBD5E1; padding: 5px 12px; border-radius: 4px; font-size: 11px;")

        btn_layout.addStretch()
        btn_layout.addWidget(btn_save)
        btn_layout.addWidget(btn_close)
        layout.addLayout(btn_layout)

        self._updating = False

    def on_width_changed(self, val):
        if self._updating or not self.chk_ratio.isChecked():
            return
        self._updating = True
        self.sb_height.setValue(int(val / self.ratio))
        self._updating = False

    def on_height_changed(self, val):
        if self._updating or not self.chk_ratio.isChecked():
            return
        self._updating = True
        self.sb_width.setValue(int(val * self.ratio))
        self._updating = False

    def get_size(self):
        return self.sb_width.value(), self.sb_height.value()


class TablePropertiesDialog(QDialog):
    """표 속성(너비, 선색, 배경색)을 변경할 수 있는 다이얼로그"""
    def __init__(self, current_width_val, current_width_type, current_border_color, current_bg_color, parent=None):
        super().__init__(parent)
        self.setWindowTitle("표 속성 변경")
        self.setFixedSize(320, 200)
        self.init_ui(current_width_val, current_width_type, current_border_color, current_bg_color)

    def init_ui(self, w_val, w_type, border_col, bg_col):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(12)

        form = QFormLayout()
        
        # Width Setup
        self.sb_width = QSpinBox()
        self.sb_width.setStyleSheet("padding: 3px; font-size: 12px;")
        
        self.combo_width_type = QComboBox()
        self.combo_width_type.addItems(["퍼센트 (%)", "픽셀 (px)"])
        self.combo_width_type.setStyleSheet("font-size: 12px;")
        
        # Set current selection
        from PyQt6.QtGui import QTextLength
        if w_type == QTextLength.Type.PercentageLength:
            self.combo_width_type.setCurrentIndex(0)
            self.sb_width.setRange(10, 100)
            self.sb_width.setValue(int(w_val) if w_val > 0 else 100)
        else:
            self.combo_width_type.setCurrentIndex(1)
            self.sb_width.setRange(50, 2000)
            self.sb_width.setValue(int(w_val) if w_val > 0 else 500)
            
        def on_type_changed(idx):
            if idx == 0: # Percentage
                self.sb_width.setRange(10, 100)
                if self.sb_width.value() > 100:
                    self.sb_width.setValue(100)
            else: # Pixel
                self.sb_width.setRange(50, 2000)
                if self.sb_width.value() <= 100:
                    self.sb_width.setValue(500)
                    
        self.combo_width_type.currentIndexChanged.connect(on_type_changed)

        width_layout = QHBoxLayout()
        width_layout.addWidget(self.sb_width)
        width_layout.addWidget(self.combo_width_type)
        form.addRow("표 너비:", width_layout)

        # Border Color Setup
        self.btn_border_color = QPushButton()
        self.btn_border_color.setFixedWidth(60)
        self.btn_border_color.setFixedHeight(24)
        self.border_color = QColor(border_col)
        self.update_button_color(self.btn_border_color, self.border_color)
        self.btn_border_color.clicked.connect(self.choose_border_color)
        form.addRow("테두리 색상:", self.btn_border_color)

        # Background Color Setup
        self.btn_bg_color = QPushButton()
        self.btn_bg_color.setFixedWidth(60)
        self.btn_bg_color.setFixedHeight(24)
        self.bg_color = QColor(bg_col)
        self.update_button_color(self.btn_bg_color, self.bg_color)
        self.btn_bg_color.clicked.connect(self.choose_bg_color)
        form.addRow("배경 색상:", self.btn_bg_color)

        layout.addLayout(form)

        # Buttons
        btn_layout = QHBoxLayout()
        btn_save = QPushButton("적용")
        btn_save.clicked.connect(self.accept)
        btn_close = QPushButton("취소")
        btn_close.clicked.connect(self.reject)

        btn_save.setStyleSheet("background-color: #2563EB; color: white; font-weight: bold; padding: 5px 12px; border-radius: 4px; font-size: 11px;")
        btn_close.setStyleSheet("background-color: #F1F5F9; color: #475569; border: 1px solid #CBD5E1; padding: 5px 12px; border-radius: 4px; font-size: 11px;")

        btn_layout.addStretch()
        btn_layout.addWidget(btn_save)
        btn_layout.addWidget(btn_close)
        layout.addLayout(btn_layout)

    def update_button_color(self, btn, color):
        btn.setStyleSheet(f"background-color: {color.name()}; border: 1px solid #CBD5E1; border-radius: 3px;")

    def choose_border_color(self):
        from PyQt6.QtWidgets import QColorDialog
        color = QColorDialog.getColor(self.border_color, self, "테두리 색상 선택")
        if color.isValid():
            self.border_color = color
            self.update_button_color(self.btn_border_color, color)

    def choose_bg_color(self):
        from PyQt6.QtWidgets import QColorDialog
        color = QColorDialog.getColor(self.bg_color, self, "배경 색상 선택")
        if color.isValid():
            self.bg_color = color
            self.update_button_color(self.btn_bg_color, color)

    def get_properties(self):
        from PyQt6.QtGui import QTextLength
        w_type = QTextLength.Type.PercentageLength if self.combo_width_type.currentIndex() == 0 else QTextLength.Type.FixedLength
        return self.sb_width.value(), w_type, self.border_color, self.bg_color


class TableSelectionOverlay(QWidget):
    """테이블 외곽에 오버레이되어 행/열/전체 선택 및 크기 조절/이동 기능을 제공하는 헤더 위젯"""
    def __init__(self, editor):
        super().__init__(editor)
        self.editor = editor
        self._table = None

    @property
    def table(self):
        from PyQt6.sip import isdeleted
        if not hasattr(self, '_table') or self._table is None:
            return None
        try:
            if isdeleted(self._table):
                self._table = None
        except Exception:
            self._table = None
        return self._table

    @table.setter
    def table(self, value):
        self._table = value

        self.row_header_width = 36
        self.column_header_height = 24
        
        self.selected_as_object = False
        self.drag_mode = None
        self.drag_start_col = None
        self.drag_current_col = None
        self.drag_start_row = None
        self.drag_current_row = None
        
        self.hovered_all = False
        self.hovered_col = None
        self.hovered_row = None
        
        self.setMouseTracking(True)
        self.hide()

    def set_target(self, table):
        self.table = table
        self.update_geometry()

    def calculate_table_geometry(self):
        if not self.table:
            return None
        from PyQt6.QtGui import QTextFormat

        num_rows = self.table.rows()
        num_cols = self.table.columns()
        padding = self.table.format().cellPadding()
        border = self.table.format().border()

        doc = self.editor.document()
        layout = doc.documentLayout()
        table_rect = layout.frameBoundingRect(self.table)

        scrollbar_value_y = self.editor.verticalScrollBar().value()
        scrollbar_value_x = self.editor.horizontalScrollBar().value()

        # frameBoundingRect는 실제 그려지는 테두리보다 padding+border만큼 안쪽 좌표를
        # 반환하므로, 셀 첫 블록의 실제 레이아웃 좌표에서 역산해 렌더 위치와 맞춘다.
        def eff_pad(cell, prop):
            cf = cell.format()
            if cf.hasProperty(prop):
                return cf.doubleProperty(prop)
            return padding

        P = QTextFormat.Property

        col_lefts_viewport = [None] * num_cols
        col_rights_viewport = [None] * num_cols
        for c in range(num_cols):
            cell = self.table.cellAt(0, c)
            if not cell.isValid():
                return None
            g = layout.blockBoundingRect(cell.firstCursorPosition().block())
            col_lefts_viewport[c] = g.x() - eff_pad(cell, P.TableCellLeftPadding) - border - scrollbar_value_x
        for c in range(num_cols - 1):
            col_rights_viewport[c] = col_lefts_viewport[c + 1]
        last_cell = self.table.cellAt(0, num_cols - 1)
        g_last = layout.blockBoundingRect(last_cell.firstCursorPosition().block())
        col_rights_viewport[num_cols - 1] = g_last.right() + eff_pad(last_cell, P.TableCellRightPadding) + border - scrollbar_value_x

        # 행 경계: 각 행 첫 블록 top에서 역산, 마지막 행은 콘텐츠 bottom 기준
        row_tops_viewport = [None] * num_rows
        row_bottoms_viewport = [None] * num_rows
        for r in range(num_rows):
            top_min = None
            for c in range(num_cols):
                cell = self.table.cellAt(r, c)
                if not cell.isValid() or cell.row() != r:
                    continue  # 병합(rowspan)으로 위 행에서 내려온 셀은 제외
                g = layout.blockBoundingRect(cell.firstCursorPosition().block())
                t = g.top() - eff_pad(cell, P.TableCellTopPadding) - border
                if top_min is None or t < top_min:
                    top_min = t
            if top_min is None:
                top_min = table_rect.top()
            row_tops_viewport[r] = top_min - scrollbar_value_y
        for r in range(num_rows - 1):
            row_bottoms_viewport[r] = row_tops_viewport[r + 1]
        bot_max = None
        for c in range(num_cols):
            cell = self.table.cellAt(num_rows - 1, c)
            if not cell.isValid():
                continue
            g = layout.blockBoundingRect(cell.lastCursorPosition().block())
            b_val = g.bottom() + eff_pad(cell, P.TableCellBottomPadding) + border
            if bot_max is None or b_val > bot_max:
                bot_max = b_val
        if bot_max is None:
            bot_max = table_rect.bottom()
        row_bottoms_viewport[num_rows - 1] = bot_max - scrollbar_value_y

        return {
            'col_lefts': col_lefts_viewport,
            'col_rights': col_rights_viewport,
            'row_tops': row_tops_viewport,
            'row_bottoms': row_bottoms_viewport,
            'width': col_rights_viewport[-1] - col_lefts_viewport[0],
            'height': row_bottoms_viewport[-1] - row_tops_viewport[0]
        }

    def update_geometry(self):
        if not self.table:
            self.hide()
            return
            
        geom = self.calculate_table_geometry()
        if not geom:
            self.hide()
            return
            
        self.col_lefts_viewport = geom['col_lefts']
        self.col_rights_viewport = geom['col_rights']
        self.row_tops_viewport = geom['row_tops']
        self.row_bottoms_viewport = geom['row_bottoms']
        self.vw = geom['width']
        self.vh = geom['height']
        
        # If the table is completely offscreen, hide the overlay to prevent drawing/interaction
        if self.row_bottoms_viewport[-1] < 0 or self.row_tops_viewport[0] > self.editor.viewport().height():
            self.hide()
            return
            
        viewport_offset_x = self.editor.viewport().x()
        viewport_offset_y = self.editor.viewport().y()
        self.overlay_x = self.col_lefts_viewport[0] - self.row_header_width + viewport_offset_x
        self.overlay_y = self.row_tops_viewport[0] - self.column_header_height + viewport_offset_y
        
        w = int(self.row_header_width + self.vw + 20)
        h = int(self.column_header_height + self.vh + 20)
            
        self.setGeometry(
            int(self.overlay_x),
            int(self.overlay_y),
            w,
            h
        )
        
        from PyQt6.QtGui import QRegion
        from PyQt6.QtCore import QRect
        
        top_rect = QRect(self.row_header_width, 0, w - self.row_header_width - 20, self.column_header_height)
        left_rect = QRect(0, self.column_header_height, self.row_header_width, h - self.column_header_height - 20)
        corner_rect = QRect(0, 0, self.row_header_width, self.column_header_height)
        
        if self.selected_as_object:
            right_rect = QRect(w - 20, 0, 20, h)
            bottom_rect = QRect(0, h - 20, w, 20)
            overlay_mask = QRegion(top_rect).united(QRegion(left_rect)).united(QRegion(corner_rect))\
                                            .united(QRegion(right_rect)).united(QRegion(bottom_rect))
        else:
            overlay_mask = QRegion(top_rect).united(QRegion(left_rect)).united(QRegion(corner_rect))
            
        viewport_rect = QRect(self.editor.viewport().pos(), self.editor.viewport().size())
        line_number_rect = QRect(self.editor.line_number_area.pos(), self.editor.line_number_area.size())
        
        allowed_region_editor = QRegion(viewport_rect).united(QRegion(line_number_rect))
        allowed_region_overlay = allowed_region_editor.translated(-self.pos())
        
        final_mask = overlay_mask.intersected(allowed_region_overlay)
        self.setMask(final_mask)
        self.show()
        self.raise_()
        self.update()

    def get_grid_lines(self):
        if not self.table or not hasattr(self, 'col_lefts_viewport'):
            return [], []
            
        cols_grid = []
        for left, right in zip(self.col_lefts_viewport, self.col_rights_viewport):
            cols_grid.append((left - self.col_lefts_viewport[0] + self.row_header_width,
                              right - self.col_lefts_viewport[0] + self.row_header_width))
            
        rows_grid = []
        for top, bottom in zip(self.row_tops_viewport, self.row_bottoms_viewport):
            rows_grid.append((top - self.row_tops_viewport[0] + self.column_header_height,
                              bottom - self.row_tops_viewport[0] + self.column_header_height))
            
        return cols_grid, rows_grid

    def get_handle_at_pos(self, pos):
        w = self.width()
        h = self.height()
        x, y = pos.x(), pos.y()
        
        if not self.selected_as_object:
            return None
            
        cell_area_w = w - 20 - self.row_header_width
            
        # Check bottom-right
        if w - 28 <= x <= w - 12 and h - 28 <= y <= h - 12:
            return "bottom-right"
        # Check right midpoint
        if w - 28 <= x <= w - 12 and int(self.column_header_height + self.vh/2 - 8) <= y <= int(self.column_header_height + self.vh/2 + 8):
            return "right"
        # Check bottom midpoint
        if int(self.row_header_width + cell_area_w/2 - 8) <= x <= int(self.row_header_width + cell_area_w/2 + 8) and h - 28 <= y <= h - 12:
            return "bottom"
            
        return None

    def mousePressEvent(self, event):
        if not self.table or event.button() != Qt.MouseButton.LeftButton:
            super().mousePressEvent(event)
            return
            
        pos = event.pos()
        cols_grid, rows_grid = self.get_grid_lines()
        
        # 1. 왼쪽 위 모서리 클릭: 테이블 이동 대기 및 오브젝트 선택 상태로 만듦
        if pos.x() < self.row_header_width and pos.y() < self.column_header_height:
            self.selected_as_object = True
            self.drag_mode = "move"
            self._drag_start_pos = event.pos()
            self.update_geometry()
            self.update()
            event.accept()
            return
            
        # 2. 크기 조절 핸들 클릭 체크
        handle = self.get_handle_at_pos(pos)
        if handle:
            self.drag_mode = handle
            self.drag_start_x = pos.x()
            self.drag_start_y = pos.y()
            self.start_widths = [right - left for left, right in cols_grid]
            self.start_heights = [bottom - top for top, bottom in rows_grid]
            event.accept()
            return
            
        # 3. 열 헤더 클릭: 열 경계선 근처이면 열 크기 조절 모드로 진입, 아니면 열 선택
        if pos.y() < self.column_header_height and pos.x() >= self.row_header_width:
            # 경계선 체크
            for c, (left, right) in enumerate(cols_grid):
                if abs(pos.x() - right) <= 4:
                    self.drag_mode = "resize_col"
                    self.resize_col_idx = c
                    self.drag_start_x = pos.x()
                    self.start_widths = [right - left for left, right in cols_grid]
                    event.accept()
                    return
            
            # 일반 영역 클릭 시 열 선택
            for c, (left, right) in enumerate(cols_grid):
                if left <= pos.x() <= right:
                    self.drag_mode = "col"
                    self.drag_start_col = c
                    self.drag_current_col = c
                    self.select_columns(c, c)
                    self.update()
                    event.accept()
                    return
                    
        # 4. 행 헤더 클릭: 행 경계선 근처이면 행 높이 조절 모드로 진입, 아니면 행 선택
        if pos.x() < self.row_header_width and pos.y() >= self.column_header_height:
            # 경계선 체크
            for r, (top, bottom) in enumerate(rows_grid):
                if abs(pos.y() - bottom) <= 4:
                    self.drag_mode = "resize_row"
                    self.resize_row_idx = r
                    self.drag_start_y = pos.y()
                    self.start_row_pad = self._row_bottom_padding(r)
                    event.accept()
                    return

            for r, (top, bottom) in enumerate(rows_grid):
                if top <= pos.y() <= bottom:
                    self.drag_mode = "row"
                    self.drag_start_row = r
                    self.drag_current_row = r
                    self.select_rows(r, r)
                    self.update()
                    event.accept()
                    return
                    
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        pos = event.pos()
        cols_grid, rows_grid = self.get_grid_lines()
        
        if self.drag_mode:
            # 이동 모드에서 드래그 시 테이블 이동(Drag & Drop) 시작
            if self.drag_mode == "move":
                from PyQt6.QtWidgets import QApplication
                if (event.pos() - self._drag_start_pos).manhattanLength() >= QApplication.startDragDistance():
                    self.start_table_drag()
                event.accept()
                return
            
            # 테이블 전체 크기 조절 드래그 처리
            elif self.drag_mode == "bottom-right":
                dx = pos.x() - self.drag_start_x
                dy = pos.y() - self.drag_start_y
                w_start = sum(self.start_widths)
                w_new = max(50, w_start + dx)
                ratio = w_new / w_start
                new_widths = [max(10, int(w * ratio)) for w in self.start_widths]
                
                from PyQt6.QtGui import QTextLength
                new_constraints = [QTextLength(QTextLength.Type.FixedLength, w) for w in new_widths]
                
                fmt = self.table.format()
                fmt.setColumnWidthConstraints(new_constraints)
                # Update total table width to match the columns' sum to prevent clashing with percentage limits
                fmt.setWidth(QTextLength(QTextLength.Type.FixedLength, sum(new_widths)))
                
                start_padding = getattr(self, "start_padding", None)
                if start_padding is None:
                    start_padding = fmt.cellPadding()
                    self.start_padding = start_padding
                new_padding = max(0.0, start_padding + dy / 20.0)
                fmt.setCellPadding(new_padding)
                
                self.table.setFormat(fmt)
                self.update_geometry()
                event.accept()
                return
                
            elif self.drag_mode == "right":
                dx = pos.x() - self.drag_start_x
                w_start = sum(self.start_widths)
                w_new = max(50, w_start + dx)
                ratio = w_new / w_start
                new_widths = [max(10, int(w * ratio)) for w in self.start_widths]
                
                from PyQt6.QtGui import QTextLength
                new_constraints = [QTextLength(QTextLength.Type.FixedLength, w) for w in new_widths]
                fmt = self.table.format()
                fmt.setColumnWidthConstraints(new_constraints)
                # Update total table width to match the columns' sum to prevent clashing with percentage limits
                fmt.setWidth(QTextLength(QTextLength.Type.FixedLength, sum(new_widths)))
                self.table.setFormat(fmt)
                self.update_geometry()
                event.accept()
                return
                
            elif self.drag_mode == "bottom":
                dy = pos.y() - self.drag_start_y
                fmt = self.table.format()
                start_padding = getattr(self, "start_padding", None)
                if start_padding is None:
                    start_padding = fmt.cellPadding()
                    self.start_padding = start_padding
                new_padding = max(0.0, start_padding + dy / 20.0)
                fmt.setCellPadding(new_padding)
                self.table.setFormat(fmt)
                self.update_geometry()
                event.accept()
                return
            
            # 열 개별 너비 조절 드래그 처리
            elif self.drag_mode == "resize_col":
                dx = pos.x() - self.drag_start_x
                c = self.resize_col_idx
                num_cols = self.table.columns()
                
                if c < num_cols - 1:
                    w_c = self.start_widths[c] + dx
                    w_c1 = self.start_widths[c+1] - dx
                    if w_c >= 20 and w_c1 >= 20:
                        new_widths = list(self.start_widths)
                        new_widths[c] = w_c
                        new_widths[c+1] = w_c1
                        
                        from PyQt6.QtGui import QTextLength
                        new_constraints = [QTextLength(QTextLength.Type.FixedLength, w) for w in new_widths]
                        fmt = self.table.format()
                        fmt.setColumnWidthConstraints(new_constraints)
                        # Update total table width to match the columns' sum to prevent clashing with percentage limits
                        fmt.setWidth(QTextLength(QTextLength.Type.FixedLength, sum(new_widths)))
                        self.table.setFormat(fmt)
                        self.update_geometry()
                else:
                    w_c = self.start_widths[c] + dx
                    if w_c >= 20:
                        new_widths = list(self.start_widths)
                        new_widths[c] = w_c
                        
                        from PyQt6.QtGui import QTextLength
                        new_constraints = [QTextLength(QTextLength.Type.FixedLength, w) for w in new_widths]
                        fmt = self.table.format()
                        fmt.setColumnWidthConstraints(new_constraints)
                        # Update total table width to match the columns' sum to prevent clashing with percentage limits
                        fmt.setWidth(QTextLength(QTextLength.Type.FixedLength, sum(new_widths)))
                        self.table.setFormat(fmt)
                        self.update_geometry()
                event.accept()
                return
                
            # 행 개별 높이 조절 드래그 처리
            elif self.drag_mode == "resize_row":
                dy = pos.y() - self.drag_start_y
                new_pad = max(0.0, self.start_row_pad + dy)
                self._set_row_bottom_padding(self.resize_row_idx, new_pad)
                self.update_geometry()
                event.accept()
                return

            elif self.drag_mode == "col":
                for c, (left, right) in enumerate(cols_grid):
                    if left <= pos.x() <= right:
                        if c != self.drag_current_col:
                            self.drag_current_col = c
                            self.select_columns(self.drag_start_col, c)
                            self.update()
                        break
            elif self.drag_mode == "row":
                for r, (top, bottom) in enumerate(rows_grid):
                    if top <= pos.y() <= bottom:
                        if r != self.drag_current_row:
                            self.drag_current_row = r
                            self.select_rows(self.drag_start_row, r)
                            self.update()
                        break
            event.accept()
            return
            
        self.hovered_all = False
        self.hovered_col = None
        self.hovered_row = None
        
        # 커서 모양 결정
        handle = self.get_handle_at_pos(pos)
        if handle == "bottom-right":
            self.setCursor(Qt.CursorShape.SizeFDiagCursor)
        elif handle == "right":
            self.setCursor(Qt.CursorShape.SizeHorCursor)
        elif handle == "bottom":
            self.setCursor(Qt.CursorShape.SizeVerCursor)
        elif pos.x() < self.row_header_width and pos.y() < self.column_header_height:
            self.setCursor(Qt.CursorShape.SizeAllCursor)
        elif pos.y() < self.column_header_height and pos.x() >= self.row_header_width:
            near_border = False
            for c, (left, right) in enumerate(cols_grid):
                if abs(pos.x() - right) <= 4:
                    near_border = True
                    break
            if near_border:
                self.setCursor(Qt.CursorShape.SplitHCursor)
            else:
                self.setCursor(Qt.CursorShape.ArrowCursor)
        elif pos.x() < self.row_header_width and pos.y() >= self.column_header_height:
            near_row_border = any(abs(pos.y() - bottom) <= 4 for top, bottom in rows_grid)
            if near_row_border:
                self.setCursor(Qt.CursorShape.SplitVCursor)
            else:
                self.setCursor(Qt.CursorShape.ArrowCursor)
        else:
            self.setCursor(Qt.CursorShape.ArrowCursor)
            
        if pos.x() < self.row_header_width and pos.y() < self.column_header_height:
            self.hovered_all = True
        elif pos.y() < self.column_header_height and pos.x() >= self.row_header_width:
            for c, (left, right) in enumerate(cols_grid):
                if left <= pos.x() <= right:
                    self.hovered_col = c
                    break
        elif pos.x() < self.row_header_width and pos.y() >= self.column_header_height:
            for r, (top, bottom) in enumerate(rows_grid):
                if top <= pos.y() <= bottom:
                    self.hovered_row = r
                    break
                    
        self.update()
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self.drag_mode = None
        if hasattr(self, "start_padding"):
            delattr(self, "start_padding")
        self.setCursor(Qt.CursorShape.ArrowCursor)
        super().mouseReleaseEvent(event)

    def leaveEvent(self, event):
        self.hovered_all = False
        self.hovered_col = None
        self.hovered_row = None
        self.setCursor(Qt.CursorShape.ArrowCursor)
        self.update()
        super().leaveEvent(event)

    def start_table_drag(self):
        from PyQt6.QtGui import QDrag
        from PyQt6.QtCore import QMimeData
        
        drag = QDrag(self.editor)
        mime_data = QMimeData()
        
        cursor = self.editor.textCursor()
        start = self.table.firstPosition() - 1
        end = self.table.lastPosition() + 1
        cursor.setPosition(start)
        cursor.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
        
        html = cursor.selection().toHtml()
        mime_data.setHtml(html)
        
        text = cursor.selection().toPlainText()
        mime_data.setText(text)
        
        drag.setMimeData(mime_data)
        self.editor.viewport().setCursor(Qt.CursorShape.ClosedHandCursor)
        
        result = drag.exec(Qt.DropAction.MoveAction)
        if result == Qt.DropAction.MoveAction:
            cursor.removeSelectedText()
                
        self.drag_mode = None
        self.editor.viewport().setCursor(Qt.CursorShape.IBeamCursor)

    def _row_bottom_padding(self, r):
        """행 r 셀들의 유효 bottom padding (개별 설정이 없으면 표 기본 cellPadding)"""
        from PyQt6.QtGui import QTextFormat
        prop = QTextFormat.Property.TableCellBottomPadding
        vals = []
        for c in range(self.table.columns()):
            cell = self.table.cellAt(r, c)
            if not cell.isValid() or cell.row() != r:
                continue
            cf = cell.format()
            if cf.hasProperty(prop):
                vals.append(cf.doubleProperty(prop))
        return max(vals) if vals else self.table.format().cellPadding()

    def _set_row_bottom_padding(self, r, pad):
        """행 r의 모든 셀 bottom padding 변경 → 행 높이 조절 효과"""
        for c in range(self.table.columns()):
            cell = self.table.cellAt(r, c)
            if not cell.isValid() or cell.row() != r:
                continue
            cf = cell.format().toTableCellFormat()
            cf.setBottomPadding(pad)
            cell.setFormat(cf)

    def select_columns(self, c_start, c_end):
        if not self.table:
            return
        num_rows = self.table.rows()
        c1 = min(c_start, c_end)
        c2 = max(c_start, c_end)
        
        cell_start = self.table.cellAt(0, c1)
        cell_end = self.table.cellAt(num_rows - 1, c2)
        if cell_start and cell_end:
            cursor = self.editor.textCursor()
            cursor.setPosition(cell_start.firstCursorPosition().position())
            cursor.setPosition(cell_end.lastCursorPosition().position(), QTextCursor.MoveMode.KeepAnchor)
            self.editor.setTextCursor(cursor)

    def select_rows(self, r_start, r_end):
        if not self.table:
            return
        num_cols = self.table.columns()
        r1 = min(r_start, r_end)
        r2 = max(r_start, r_end)
        
        cell_start = self.table.cellAt(r1, 0)
        cell_end = self.table.cellAt(r2, num_cols - 1)
        if cell_start and cell_end:
            cursor = self.editor.textCursor()
            cursor.setPosition(cell_start.firstCursorPosition().position())
            cursor.setPosition(cell_end.lastCursorPosition().position(), QTextCursor.MoveMode.KeepAnchor)
            self.editor.setTextCursor(cursor)

    def select_all_table(self):
        if not self.table:
            return
        num_rows = self.table.rows()
        num_cols = self.table.columns()
        cell_start = self.table.cellAt(0, 0)
        cell_end = self.table.cellAt(num_rows - 1, num_cols - 1)
        if cell_start and cell_end:
            cursor = self.editor.textCursor()
            cursor.setPosition(cell_start.firstCursorPosition().position())
            cursor.setPosition(cell_end.lastCursorPosition().position(), QTextCursor.MoveMode.KeepAnchor)
            self.editor.setTextCursor(cursor)

    def paintEvent(self, event):
        if not self.table:
            return
        
        from PyQt6.QtGui import QPainter, QColor, QPen, QFont
        from PyQt6.QtCore import QRect
        
        painter = QPainter(self)
        painter.setFont(QFont("Malgun Gothic", 9, QFont.Weight.DemiBold))
        
        cols_grid, rows_grid = self.get_grid_lines()
        if not cols_grid or not rows_grid:
            return
            
        w = self.width()
        h = self.height()
            
        def get_column_label(c):
            label = ""
            while c >= 0:
                label = chr(65 + (c % 26)) + label
                c = (c // 26) - 1
            return label
            
        # 1. 왼쪽 위 모서리 (이동 핸들로 변경)
        corner_rect = QRect(0, 0, self.row_header_width, self.column_header_height)
        if self.hovered_all:
            painter.fillRect(corner_rect, QColor("#3B82F6"))
            painter.setPen(QColor("#FFFFFF"))
        else:
            painter.fillRect(corner_rect, QColor("#F1F5F9"))
            painter.setPen(QColor("#64748B"))
        painter.drawRect(corner_rect)
        
        # 4방향 이동 화살표 그리기 (동적으로 중심 정렬)
        cx = self.row_header_width // 2
        cy = self.column_header_height // 2
        painter.drawLine(cx, cy - 6, cx, cy + 6)
        painter.drawLine(cx - 6, cy, cx + 6, cy)
        painter.drawLine(cx - 2, cy - 4, cx, cy - 6)
        painter.drawLine(cx + 2, cy - 4, cx, cy - 6)
        painter.drawLine(cx - 2, cy + 4, cx, cy + 6)
        painter.drawLine(cx + 2, cy + 4, cx, cy + 6)
        painter.drawLine(cx - 4, cy - 2, cx - 6, cy)
        painter.drawLine(cx - 4, cy + 2, cx - 6, cy)
        painter.drawLine(cx + 4, cy - 2, cx + 6, cy)
        painter.drawLine(cx + 4, cy + 2, cx + 6, cy)
        
        curr_cursor = self.editor.textCursor()
        sel_first_row, sel_num_rows, sel_first_col, sel_num_cols = -1, 0, -1, 0
        if curr_cursor.hasSelection() and curr_cursor.selectedTableCells() != (-1, -1, -1, -1):
            sel_first_row, sel_num_rows, sel_first_col, sel_num_cols = curr_cursor.selectedTableCells()
            
        # 2. Paint top headers
        for c, (left, right) in enumerate(cols_grid):
            header_rect = QRect(int(left), 0, int(right - left), self.column_header_height)
            
            is_selected = False
            if sel_first_col != -1:
                is_selected = (sel_first_col <= c < sel_first_col + sel_num_cols)
                
            if self.hovered_col == c:
                bg_color = QColor("#DBEAFE")
                border_color = QColor("#3B82F6")
            elif is_selected:
                bg_color = QColor("#BFDBFE")
                border_color = QColor("#2563EB")
            else:
                bg_color = QColor("#F8FAFC")
                border_color = QColor("#CBD5E1")
                
            painter.fillRect(header_rect, bg_color)
            painter.setPen(QPen(border_color, 1))
            painter.drawRect(header_rect)
            
            painter.setPen(QColor("#475569"))
            label = get_column_label(c)
            painter.drawText(header_rect, Qt.AlignmentFlag.AlignCenter, label)
            
        # 3. Paint left headers
        for r, (top, bottom) in enumerate(rows_grid):
            header_rect = QRect(0, int(top), self.row_header_width, int(bottom - top))
            
            is_selected = False
            if sel_first_row != -1:
                is_selected = (sel_first_row <= r < sel_first_row + sel_num_rows)
                
            if self.hovered_row == r:
                bg_color = QColor("#DBEAFE")
                border_color = QColor("#3B82F6")
            elif is_selected:
                bg_color = QColor("#BFDBFE")
                border_color = QColor("#2563EB")
            else:
                bg_color = QColor("#F8FAFC")
                border_color = QColor("#CBD5E1")
                
            painter.fillRect(header_rect, bg_color)
            painter.setPen(QPen(border_color, 1))
            painter.drawRect(header_rect)
            
            painter.setPen(QColor("#475569"))
            label = str(r + 1)
            painter.drawText(header_rect, Qt.AlignmentFlag.AlignCenter, label)
            
        # 4. 오브젝트로 선택 시 외곽선 및 크기 조절 핸들 점 그리기
        if self.selected_as_object:
            pen = QPen(QColor("#2563EB"), 1.5, Qt.PenStyle.DashLine)
            painter.setPen(pen)
            cell_area_w = w - 20 - self.row_header_width
            painter.drawRect(self.row_header_width, self.column_header_height, cell_area_w, h - self.column_header_height - 20)
            
            painter.setBrush(QColor("#2563EB"))
            painter.setPen(Qt.PenStyle.NoPen)
            
            # 우측 하단 핸들
            painter.drawRect(w - 24, h - 24, 8, 8)
            # 우측 중간 핸들
            painter.drawRect(w - 24, int(self.column_header_height + self.vh/2 - 4), 8, 8)
            # 하단 중간 핸들
            painter.drawRect(int(self.row_header_width + cell_area_w // 2 - 4), h - 24, 8, 8)



class ImageSelectionOverlay(QWidget):
    """선택된 이미지 위에 오버레이되어 드래그 크기 조절 핸들을 제공하는 위젯"""
    def __init__(self, editor):
        super().__init__(editor.viewport())
        self.editor = editor
        self.cursor = None
        self.image_format = None
        self.resizing = False
        self.handle_clicked = None
        self.drag_start_pos = None
        self.drag_start_size = None
        
        self.handle_size = 8
        self.setMouseTracking(True)
        self.hide()

    def set_target(self, cursor, image_format):
        self.cursor = cursor
        self.image_format = image_format
        self.update_geometry()
        self.show()

    def update_geometry(self):
        if not self.cursor or not self.image_format:
            self.hide()
            return
        
        start_cursor = QTextCursor(self.editor.document())
        start_cursor.setPosition(self.cursor.anchor() if self.cursor.anchor() < self.cursor.position() else self.cursor.position())
        rect_start = self.editor.cursorRect(start_cursor)
        
        w = self.image_format.width()
        h = self.image_format.height()
        if w <= 0 or h <= 0:
            orig_size = self.editor.get_image_original_size(self.image_format.name())
            if orig_size:
                w = w if w > 0 else orig_size.width()
                h = h if h > 0 else orig_size.height()
            else:
                w, h = 400, 300
            
        self.setGeometry(rect_start.x(), rect_start.y(), int(w), int(h))
        self.show()
        self.raise_()
        self.update()

    def paintEvent(self, event):
        from PyQt6.QtGui import QPainter, QPen
        painter = QPainter(self)
        
        # Draw border
        pen = QPen(QColor("#2563EB"), 1.5, Qt.PenStyle.DashLine)
        painter.setPen(pen)
        painter.drawRect(0, 0, self.width() - 1, self.height() - 1)
        
        # Draw 8 handles
        painter.setBrush(QColor("#2563EB"))
        painter.setPen(Qt.PenStyle.NoPen)
        hs = self.handle_size
        w, h = self.width(), self.height()
        
        # Corners
        painter.drawRect(0, 0, hs, hs)  # top-left
        painter.drawRect(w - hs, 0, hs, hs)  # top-right
        painter.drawRect(0, h - hs, hs, hs)  # bottom-left
        painter.drawRect(w - hs, h - hs, hs, hs)  # bottom-right
        
        # Sides
        painter.drawRect(0, int(h/2 - hs/2), hs, hs)  # left
        painter.drawRect(w - hs, int(h/2 - hs/2), hs, hs)  # right
        painter.drawRect(int(w/2 - hs/2), 0, hs, hs)  # top
        painter.drawRect(int(w/2 - hs/2), h - hs, hs, hs)  # bottom

    def get_handle_at_pos(self, pos):
        hs = self.handle_size
        x, y = pos.x(), pos.y()
        w, h = self.width(), self.height()
        
        def in_rect(rx, ry):
            return rx <= x <= rx + hs and ry <= y <= ry + hs
            
        # Check corners first for precision
        if in_rect(0, 0): return "top-left"
        if in_rect(w - hs, 0): return "top-right"
        if in_rect(0, h - hs): return "bottom-left"
        if in_rect(w - hs, h - hs): return "bottom-right"
        
        # Check sides
        if in_rect(0, h/2 - hs/2): return "left"
        if in_rect(w - hs, h/2 - hs/2): return "right"
        if in_rect(w/2 - hs/2, 0): return "top"
        if in_rect(w/2 - hs/2, h - hs): return "bottom"
        
        return None

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            handle = self.get_handle_at_pos(event.pos())
            if handle:
                self.resizing = True
                self.handle_clicked = handle
                self.drag_start_pos = event.globalPosition()
                self.drag_start_size = (self.width(), self.height())
                event.accept()
                return
        # Propagate click inside image to editor for selection and native drag
        event.ignore()

    def mouseMoveEvent(self, event):
        hs = self.handle_size
        handle = self.get_handle_at_pos(event.pos())
        
        if self.resizing:
            if self.handle_clicked in ["top-left", "bottom-right"]:
                self.setCursor(Qt.CursorShape.SizeFDiagCursor)
            elif self.handle_clicked in ["top-right", "bottom-left"]:
                self.setCursor(Qt.CursorShape.SizeBDiagCursor)
            elif self.handle_clicked in ["left", "right"]:
                self.setCursor(Qt.CursorShape.SizeHorCursor)
            elif self.handle_clicked in ["top", "bottom"]:
                self.setCursor(Qt.CursorShape.SizeVerCursor)
        else:
            if handle in ["top-left", "bottom-right"]:
                self.setCursor(Qt.CursorShape.SizeFDiagCursor)
            elif handle in ["top-right", "bottom-left"]:
                self.setCursor(Qt.CursorShape.SizeBDiagCursor)
            elif handle in ["left", "right"]:
                self.setCursor(Qt.CursorShape.SizeHorCursor)
            elif handle in ["top", "bottom"]:
                self.setCursor(Qt.CursorShape.SizeVerCursor)
            else:
                self.setCursor(Qt.CursorShape.OpenHandCursor)
            
        if self.resizing and self.drag_start_pos:
            delta = event.globalPosition() - self.drag_start_pos
            dx = int(delta.x())
            dy = int(delta.y())
            
            w_start, h_start = self.drag_start_size
            ratio = w_start / h_start if h_start > 0 else 1.0
            
            new_w, new_h = w_start, h_start
            if self.handle_clicked == "bottom-right":
                new_w = max(20, w_start + dx)
                new_h = max(20, h_start + dy)
            elif self.handle_clicked == "bottom-left":
                new_w = max(20, w_start - dx)
                new_h = max(20, h_start + dy)
            elif self.handle_clicked == "top-right":
                new_w = max(20, w_start + dx)
                new_h = max(20, h_start - dy)
            elif self.handle_clicked == "top-left":
                new_w = max(20, w_start - dx)
                new_h = max(20, h_start - dy)
            elif self.handle_clicked == "left":
                new_w = max(20, w_start - dx)
            elif self.handle_clicked == "right":
                new_w = max(20, w_start + dx)
            elif self.handle_clicked == "top":
                new_h = max(20, h_start - dy)
            elif self.handle_clicked == "bottom":
                new_h = max(20, h_start + dy)
                
            # 모서리 조절 시 Shift 키가 눌린 경우에만 정비율(종횡비) 고정
            if self.handle_clicked in ["top-left", "top-right", "bottom-left", "bottom-right"]:
                if event.modifiers() & Qt.KeyboardModifier.ShiftModifier:
                    if abs(dx) > abs(dy):
                        new_h = int(new_w / ratio)
                    else:
                        new_w = int(new_h * ratio)
                    
            self.image_format.setWidth(new_w)
            self.image_format.setHeight(new_h)
            
            self.cursor.setCharFormat(self.image_format)
            self.update_geometry()
            event.accept()
            return
        event.ignore()

    def mouseReleaseEvent(self, event):
        if self.resizing:
            self.resizing = False
            self.handle_clicked = None
            self.drag_start_pos = None
            self.setCursor(Qt.CursorShape.ArrowCursor)
            event.accept()
            return
        event.ignore()





class DragMenuButton(QPushButton):
    """드래그 앤 드롭으로 순서 변경이 가능한 사이드바 메뉴 버튼"""
    def __init__(self, text, parent=None):
        super().__init__(text, parent)
        self.drag_start_pos = None

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.drag_start_pos = event.pos()
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if event.buttons() & Qt.MouseButton.LeftButton and self.drag_start_pos:
            from PyQt6.QtWidgets import QApplication
            if (event.pos() - self.drag_start_pos).manhattanLength() >= QApplication.startDragDistance():
                from PyQt6.QtGui import QDrag
                from PyQt6.QtCore import QMimeData
                
                drag = QDrag(self)
                mime = QMimeData()
                mime.setText(self.text())
                drag.setMimeData(mime)
                
                pixmap = self.grab()
                drag.setPixmap(pixmap)
                drag.setHotSpot(event.pos())
                
                drag.exec(Qt.DropAction.MoveAction)
        super().mouseMoveEvent(event)


class DragMenuContainer(QWidget):
    """드래그 앤 드롭 메뉴 버튼을 담는 컨테이너 위젯"""
    order_changed = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        # 드롭 위치를 나타내는 인디케이터 라인
        self.indicator = QWidget(self)
        self.indicator.setStyleSheet("background-color: #3B82F6; border-radius: 2px;")
        self.indicator.setFixedHeight(4)
        self.indicator.hide()

    def dragEnterEvent(self, event):
        if event.mimeData().hasText():
            event.acceptProposedAction()
            self.indicator.show()

    def dragMoveEvent(self, event):
        if event.mimeData().hasText():
            event.acceptProposedAction()
            y = event.position().y()
            layout = self.layout()
            if not layout:
                return
            
            target_idx = 0
            for i in range(layout.count()):
                w = layout.itemAt(i).widget()
                if w and w != self.indicator:
                    center_y = w.geometry().y() + w.geometry().height() / 2
                    if y > center_y:
                        target_idx = i + 1
                    else:
                        break
                        
            if target_idx < layout.count():
                target_widget = layout.itemAt(target_idx).widget()
                if target_widget and target_widget != self.indicator:
                    self.indicator.move(2, target_widget.geometry().top() - 6)
            else:
                last_widget = None
                for i in range(layout.count() - 1, -1, -1):
                    w = layout.itemAt(i).widget()
                    if w and w != self.indicator:
                        last_widget = w
                        break
                if last_widget:
                    self.indicator.move(2, last_widget.geometry().bottom() + 2)
            
            self.indicator.resize(self.width() - 4, 4)

    def dragLeaveEvent(self, event):
        self.indicator.hide()

    def dropEvent(self, event):
        self.indicator.hide()
        text = event.mimeData().text()
        layout = self.layout()
        if not layout:
            return
            
        dragged_button = None
        for i in range(layout.count()):
            w = layout.itemAt(i).widget()
            if isinstance(w, DragMenuButton) and w.text() == text:
                dragged_button = w
                break
                
        if dragged_button:
            y = event.position().y()
            widgets = []
            for i in range(layout.count()):
                w = layout.itemAt(i).widget()
                if w and w != self.indicator and w != dragged_button:
                    widgets.append(w)
            
            insert_before_idx = len(widgets)
            for idx, w in enumerate(widgets):
                center_y = w.geometry().y() + w.geometry().height() / 2
                if y < center_y:
                    insert_before_idx = idx
                    break
            
            layout.removeWidget(dragged_button)
            layout.insertWidget(insert_before_idx, dragged_button)
            event.acceptProposedAction()
            self.order_changed.emit()


class LineNumberArea(QWidget):
    """RichTextEdit의 왼쪽에 행 번호를 표시하기 위한 영역 위젯"""
    def __init__(self, editor):
        super().__init__(editor)
        self.editor = editor

    def sizeHint(self):
        return QSize(self.editor.line_number_area_width(), 0)

    def paintEvent(self, event):
        self.editor.line_number_area_paint_event(event)


class RichTextEdit(QTextEdit):
    def apply_document_margins(self):
        from PyQt6.QtGui import QTextLength
        doc = self.document()
        doc.setDocumentMargin(0)
        root_frame = doc.rootFrame()
        if root_frame:
            fmt = root_frame.frameFormat()
            fmt.setLeftMargin(8)
            fmt.setRightMargin(8)
            fmt.setTopMargin(2)
            fmt.setBottomMargin(10)
            fmt.setWidth(QTextLength(QTextLength.Type.VariableLength, 0.0))
            root_frame.setFrameFormat(fmt)

    def setHtml(self, html):
        super().setHtml(html)
        self.apply_document_margins()
        self.update_table_blocks()
        p = self.parent()
        while p:
            if hasattr(p, "clear_search_highlights"):
                p.clear_search_highlights()
                if hasattr(p, "search_panel") and p.search_panel.isVisible():
                    p.search_panel.hide()
                break
            p = p.parent()

    def setPlainText(self, text):
        super().setPlainText(text)
        self.apply_document_margins()
        self.update_table_blocks()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.apply_document_margins()
        self.image_overlay = ImageSelectionOverlay(self)
        self.table_overlay = TableSelectionOverlay(self)
        self.line_number_area = LineNumberArea(self)
        
        self.verticalScrollBar().valueChanged.connect(self.image_overlay.update_geometry)
        self.horizontalScrollBar().valueChanged.connect(self.image_overlay.update_geometry)
        self.textChanged.connect(self.image_overlay.update_geometry)
        
        self.verticalScrollBar().valueChanged.connect(self.table_overlay.update_geometry)
        self.horizontalScrollBar().valueChanged.connect(self.table_overlay.update_geometry)
        self.textChanged.connect(self.table_overlay.update_geometry)
        
        self.cursorPositionChanged.connect(self.on_cursor_position_changed)
        
        self.document().documentLayout().update.connect(self.update_line_number_area)
        self.verticalScrollBar().valueChanged.connect(self.update_line_number_area)
        self.textChanged.connect(self.update_line_number_area)
        self.textChanged.connect(self.update_table_blocks)
        
        self.setMouseTracking(True)
        self.viewport().setMouseTracking(True)
        self._image_pressed = False
        self._press_pos = None
        
        self.table_blocks = {}
        self.update_table_blocks()
        self.update_margins()

    def update_table_blocks(self):
        print("update_table_blocks started")
        from PyQt6.QtGui import QTextTable
        document = self.document()
        
        def find_tables(frame):
            tables = []
            if isinstance(frame, QTextTable):
                tables.append(frame)
            for child in frame.childFrames():
                tables.extend(find_tables(child))
            return tables
            
        tables = find_tables(document.rootFrame())
        self.table_blocks = {}
        for t in tables:
            obj_idx = t.objectIndex()
            for r in range(t.rows()):
                for c in range(t.columns()):
                    cell = t.cellAt(r, c)
                    if cell.isValid():
                        first_block = cell.firstCursorPosition().block()
                        last_block = cell.lastCursorPosition().block()
                        curr = first_block
                        while curr.isValid() and curr.blockNumber() <= last_block.blockNumber():
                            self.table_blocks[curr.blockNumber()] = obj_idx
                            if curr.blockNumber() == last_block.blockNumber():
                                break
                            curr = curr.next()
        print("update_table_blocks completed. Block count:", len(self.table_blocks))

    def line_number_area_width(self):
        digits = 1
        max_num = max(1, self.document().blockCount())
        while max_num >= 10:
            max_num /= 10
            digits += 1
        space = 15 + self.fontMetrics().horizontalAdvance('9') * digits
        return space

    def update_margins(self):
        from PyQt6.QtGui import QTextLength
        self.setViewportMargins(self.line_number_area_width(), 0, 0, 0)
        root_frame = self.document().rootFrame()
        if root_frame:
            fmt = root_frame.frameFormat()
            if (fmt.leftMargin() != 8 or fmt.rightMargin() != 8 or 
                fmt.topMargin() != 2 or fmt.bottomMargin() != 10 or 
                fmt.width().type() != QTextLength.Type.VariableLength):
                fmt.setLeftMargin(8)
                fmt.setRightMargin(8)
                fmt.setTopMargin(2)
                fmt.setBottomMargin(10)
                fmt.setWidth(QTextLength(QTextLength.Type.VariableLength, 0.0))
                root_frame.setFrameFormat(fmt)

    def update_line_number_area(self, *args):
        self.update_margins()
        self.line_number_area.update()
        self.image_overlay.update_geometry()
        self.table_overlay.update_geometry()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        cr = self.contentsRect()
        self.line_number_area.setGeometry(cr.left(), cr.top(), self.line_number_area_width(), cr.height())
        self.table_overlay.update_geometry()

    def keyPressEvent(self, event):
        print("keyPressEvent called. Key:", event.key())
        # 1. 만약 표가 오버레이로 선택된 상태(selected_as_object)에서 Delete나 Backspace를 누르면 표 삭제
        if self.table_overlay.isVisible() and self.table_overlay.table and self.table_overlay.selected_as_object:
            print("table overlay is visible, has table, selected_as_object is True")
            if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
                print("Delete/Backspace detected")
                t = self.table_overlay.table
                print("table:", t)
                start = t.firstPosition() - 1
                end = t.lastPosition() + 1
                print("start:", start, "end:", end)
                new_cursor = QTextCursor(self.document())
                print("new_cursor created")
                new_cursor.setPosition(start)
                print("setPosition start done")
                new_cursor.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
                print("setPosition end KeepAnchor done")
                
                # Hide overlay first, before modifying document, to avoid any layout update/paint event using deleted table!
                self.hide_table_overlay()
                print("hide_table_overlay done")

                # Block signals to avoid recursive callbacks while layout is in intermediate state
                self.blockSignals(True)
                self.document().blockSignals(True)
                try:
                    new_cursor.removeSelectedText()
                    print("new_cursor removeSelectedText done")
                finally:
                    self.document().blockSignals(False)
                    self.blockSignals(False)
                
                # Explicitly trigger update
                self.update_table_blocks()
                self.setTextCursor(new_cursor)
                print("setTextCursor done")
                event.accept()
                return
        
        # 2. 이미지 오버레이가 선택된 상태에서 Delete나 Backspace를 누르면 이미지 삭제
        elif self.image_overlay.isVisible() and self.image_overlay.cursor:
            if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
                cursor = self.image_overlay.cursor
                self.setTextCursor(cursor)
                self.textCursor().removeSelectedText()
                self.hide_image_overlay()
                event.accept()
                return
                
        super().keyPressEvent(event)

    def table_visual_bounds(self, layout, t):
        """표가 실제로 그려지는 top/bottom (frameBoundingRect는 padding+border만큼
        안쪽/아래쪽으로 어긋난 좌표를 반환하므로 셀 블록 좌표로 역산)"""
        from PyQt6.QtGui import QTextFormat
        fmt = t.format()
        padding = fmt.cellPadding()
        border = fmt.border()
        prop_top = QTextFormat.Property.TableCellTopPadding
        prop_bot = QTextFormat.Property.TableCellBottomPadding
        table_rect = layout.frameBoundingRect(t)
        try:
            first_cell = t.cellAt(0, 0)
            cf = first_cell.format()
            top_pad = cf.doubleProperty(prop_top) if cf.hasProperty(prop_top) else padding
            g = layout.blockBoundingRect(first_cell.firstCursorPosition().block())
            visual_top = g.top() - top_pad - border
            visual_bottom = None
            last_row = t.rows() - 1
            for c in range(t.columns()):
                cell = t.cellAt(last_row, c)
                if not cell.isValid():
                    continue
                cf = cell.format()
                bot_pad = cf.doubleProperty(prop_bot) if cf.hasProperty(prop_bot) else padding
                gb = layout.blockBoundingRect(cell.lastCursorPosition().block())
                b_val = gb.bottom() + bot_pad + border
                if visual_bottom is None or b_val > visual_bottom:
                    visual_bottom = b_val
            if visual_bottom is None:
                visual_bottom = table_rect.bottom()
            return visual_top, visual_bottom
        except Exception:
            return table_rect.top(), table_rect.bottom()

    def line_number_area_paint_event(self, event):
        from PyQt6.QtGui import QPainter, QColor, QFont
        painter = QPainter(self.line_number_area)
        painter.fillRect(event.rect(), QColor("#F8FAFC")) # slate 50
        
        painter.setPen(QColor("#E2E8F0")) # slate 200
        painter.drawLine(self.line_number_area.width() - 1, 0, self.line_number_area.width() - 1, self.line_number_area.height())
        
        document = self.document()
        layout = document.documentLayout()
        scrollbar_value = self.verticalScrollBar().value()
        
        painter.setPen(QColor("#94A3B8")) # slate 400
        font = QFont("Consolas", 10)
        painter.setFont(font)
        
        # 표 영역을 미리 검색하여 각 표의 실제 셀 영역(top ~ bottom) 수집
        tables = []
        def find_tables(frame):
            from PyQt6.QtGui import QTextTable
            for child in frame.childFrames():
                if isinstance(child, QTextTable):
                    tables.append(child)
                find_tables(child)
        find_tables(document.rootFrame())
        table_cell_bounds = {}
        for t in tables:
            obj_idx = t.objectIndex()
            table_cell_bounds[obj_idx] = self.table_visual_bounds(layout, t)
            
        block = document.begin()
        block_number = 1
        numbered_tables = set()
        current_y_limit = 0
        
        while block.isValid():
            block_num = block.blockNumber()
            table_idx = self.table_blocks.get(block_num)
            
            should_draw = True
            should_increment = True
            
            block_geometry = layout.blockBoundingRect(block)
            y_top = block_geometry.top()
            y_bottom_val = block_geometry.bottom()
            
            if table_idx is not None:
                t_bounds = table_cell_bounds.get(table_idx)
                if t_bounds:
                    t_top, t_bottom = t_bounds
                    if table_idx not in numbered_tables:
                        y_top = t_top
                        y_bottom_val = t_bottom
                        current_y_limit = max(current_y_limit, t_bottom)
                    else:
                        should_draw = False
                        should_increment = False
                        current_y_limit = max(current_y_limit, t_bottom)
            else:
                current_y_limit = max(current_y_limit, y_bottom_val)
                
            # Check if this block is inside any table's vertical span
            is_inside_table_span = False
            for t in tables:
                t_bounds = table_cell_bounds.get(t.objectIndex())
                if t_bounds:
                    t_top, t_bottom = t_bounds
                    # 표 앞뒤에 빈 블록이 존재할 때 표 외부 블록(구분선)으로
                    # 인식하므로 여유(-3px)를 두고 표 내부인지 확인을 필터링한다
                    if t_top - 3 <= y_top < t_bottom - 1 and (table_idx is not None or block.text() == ''):
                        is_inside_table_span = True
                        break
            
            if is_inside_table_span and table_idx is None:
                should_draw = False
                should_increment = False
                    
            if should_draw:
                y_top_vp = y_top - scrollbar_value
                y_bottom_vp = y_bottom_val - scrollbar_value
                
                if y_bottom_vp >= 0 and y_top_vp <= self.viewport().height():
                    text = str(block_number)
                    painter.drawText(
                        0, int(y_top_vp), 
                        self.line_number_area.width() - 6, self.fontMetrics().height(),
                        Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignTop, 
                        text
                    )
                
            if table_idx is not None:
                numbered_tables.add(table_idx)
                
            block = block.next()
            if should_increment:
                block_number += 1
 
    def paintEvent(self, event):
        super().paintEvent(event)
        
        from PyQt6.QtGui import QPainter, QColor, QTextTable
        painter = QPainter(self.viewport())
        painter.setPen(QColor("#F1F5F9")) # slate 100
        
        document = self.document()
        layout = document.documentLayout()
        scrollbar_value = self.verticalScrollBar().value()
        
        # 표 영역을 찾아 가이드라인이 표 내부를 가로지르지 않도록 클리핑 처리
        tables = []
        def find_tables(frame):
            for child in frame.childFrames():
                if isinstance(child, QTextTable):
                    tables.append(child)
                find_tables(child)
        find_tables(document.rootFrame())
        table_cell_bounds = {}
        for t in tables:
            obj_idx = t.objectIndex()
            table_cell_bounds[obj_idx] = self.table_visual_bounds(layout, t)
            
        block = document.begin()
        numbered_tables = set()
        drawn_segment_ys = set()
        horizontal_scrollbar_val = self.horizontalScrollBar().value()
        
        # Calculate guideline boundaries exactly matching the text wrapping boundary
        line_start_x = 8
        line_end_x = self.viewport().width() - 8
        current_y_limit = 0
        
        while block.isValid():
            block_num = block.blockNumber()
            table_idx = self.table_blocks.get(block_num)
            
            should_draw = True
            
            block_geometry = layout.blockBoundingRect(block)
            y_top = block_geometry.top()
            y_bottom_val = block_geometry.bottom()
            
            if table_idx is not None:
                t_bounds = table_cell_bounds.get(table_idx)
                if t_bounds:
                    t_top, t_bottom = t_bounds
                    if table_idx not in numbered_tables:
                        y_top = t_top
                        y_bottom_val = t_bottom
                        current_y_limit = max(current_y_limit, t_bottom)
                    else:
                        should_draw = False
                        current_y_limit = max(current_y_limit, t_bottom)
            else:
                current_y_limit = max(current_y_limit, y_bottom_val)
                
            y_bottom_vp = y_bottom_val - scrollbar_value
            
            # Check if this line overlaps with any table vertical span
            overlapping_table = None
            for t in tables:
                t_bounds = table_cell_bounds.get(t.objectIndex())
                if t_bounds:
                    t_top, t_bottom = t_bounds
                    if t_top <= y_bottom_val <= t_bottom:
                        overlapping_table = t
                        break
                        
            # Check if the block is empty and inside the table span (empty block immediately after table)
            is_inside_table_span = False
            for t in tables:
                t_bounds = table_cell_bounds.get(t.objectIndex())
                if t_bounds:
                    t_top, t_bottom = t_bounds
                    # 표 앞뒤에 빈 블록이 존재할 때 표 외부 블록(구분선)으로
                    # 인식하므로 여유(-3px)를 두고 표 내부인지 확인을 필터링한다
                    if t_top - 3 <= y_top < t_bottom - 1 and (table_idx is not None or block.text() == ''):
                        is_inside_table_span = True
                        break
                        
            if is_inside_table_span and table_idx is None:
                should_draw = False
                
            if should_draw:
                if y_bottom_vp >= 0 and y_bottom_vp <= self.viewport().height():
                    y_key = int(y_bottom_vp)
                    if overlapping_table is not None:
                        if y_key not in drawn_segment_ys:
                            drawn_segment_ys.add(y_key)
                            t_rect = layout.frameBoundingRect(overlapping_table)
                            t_left = t_rect.x() - horizontal_scrollbar_val
                            # Draw left segment
                            if line_start_x < t_left:
                                painter.drawLine(line_start_x, y_key, int(t_left), y_key)
                    else:
                        if table_idx is None and not is_inside_table_span:
                            painter.drawLine(line_start_x, y_key, line_end_x, y_key)
                
            if table_idx is not None:
                numbered_tables.add(table_idx)
                
            block = block.next()

    def on_cursor_position_changed(self):
        cursor = self.textCursor()
        
        # 1. 커서가 표 내부에 있는 경우 해당 표 오버레이 표시
        table = cursor.currentTable()
        if table:
            if self.table_overlay.table != table:
                self.show_table_overlay(table)
                self.table_overlay.selected_as_object = False
            self.hide_image_overlay()
            return
            
        # 2. 커서 선택 영역이 표를 감싸고 있는 경우
        if cursor.hasSelection():
            document = self.document()
            tables = []
            def find_tables(frame):
                for child in frame.childFrames():
                    if isinstance(child, QTextTable):
                        tables.append(child)
                    find_tables(child)
            find_tables(document.rootFrame())
            
            selected_t = None
            for t in tables:
                t_start = t.firstPosition() - 1
                t_end = t.lastPosition() + 1
                if (cursor.anchor() == t_start and cursor.position() == t_end) or \
                   (cursor.anchor() == t_end and cursor.position() == t_start):
                    selected_t = t
                    break
            
            if selected_t:
                self.show_table_overlay(selected_t)
                self.hide_image_overlay()
                return

        self.hide_table_overlay()

        if cursor.hasSelection():
            if abs(cursor.position() - cursor.anchor()) == 1:
                helper = QTextCursor(cursor)
                helper.setPosition(min(cursor.position(), cursor.anchor()))
                helper.movePosition(QTextCursor.MoveOperation.NextCharacter, QTextCursor.MoveMode.KeepAnchor)
                if helper.charFormat().isImageFormat():
                    self.show_image_overlay(helper, helper.charFormat().toImageFormat())
                    return
        self.hide_image_overlay()

    def show_image_overlay(self, cursor, image_format):
        self.image_overlay.set_target(cursor, image_format)

    def hide_image_overlay(self):
        self.image_overlay.cursor = None
        self.image_overlay.image_format = None
        self.image_overlay.hide()

    def show_table_overlay(self, table):
        self.table_overlay.set_target(table)

    def hide_table_overlay(self):
        self.table_overlay.table = None
        self.table_overlay.selected_as_object = False
        self.table_overlay.hide()

    def get_image_at_pos(self, pos):
        from PyQt6.QtCore import QRect
        cursor = self.cursorForPosition(pos)
        
        c_prev = QTextCursor(self.document())
        c_prev.setPosition(cursor.position())
        c_prev.movePosition(QTextCursor.MoveOperation.PreviousCharacter, QTextCursor.MoveMode.KeepAnchor)
        if c_prev.charFormat().isImageFormat():
            fmt = c_prev.charFormat().toImageFormat()
            start_pos = c_prev.anchor() if c_prev.anchor() < c_prev.position() else c_prev.position()
            start_cursor = QTextCursor(self.document())
            start_cursor.setPosition(start_pos)
            rect_start = self.cursorRect(start_cursor)
            w = fmt.width()
            h = fmt.height()
            if w <= 0 or h <= 0:
                w, h = 400, 300
            img_rect = QRect(rect_start.x(), rect_start.y(), int(w), int(h))
            if img_rect.contains(pos):
                return c_prev, fmt
                
        c_next = QTextCursor(self.document())
        c_next.setPosition(cursor.position())
        c_next.movePosition(QTextCursor.MoveOperation.NextCharacter, QTextCursor.MoveMode.KeepAnchor)
        if c_next.charFormat().isImageFormat():
            fmt = c_next.charFormat().toImageFormat()
            start_pos = c_next.anchor() if c_next.anchor() < c_next.position() else c_next.position()
            start_cursor = QTextCursor(self.document())
            start_cursor.setPosition(start_pos)
            rect_start = self.cursorRect(start_cursor)
            w = fmt.width()
            h = fmt.height()
            if w <= 0 or h <= 0:
                w, h = 400, 300
            img_rect = QRect(rect_start.x(), rect_start.y(), int(w), int(h))
            if img_rect.contains(pos):
                return c_next, fmt
                
        return None, None

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            # 1. 표 테두리 클릭 체크 (클릭 시 표 전체 선택 및 드래그 준비)
            document = self.document()
            layout = document.documentLayout()
            scrollbar_value = self.verticalScrollBar().value()
            
            tables = []
            def find_tables(frame):
                for child in frame.childFrames():
                    if isinstance(child, QTextTable):
                        tables.append(child)
                    find_tables(child)
            find_tables(document.rootFrame())
            
            from PyQt6.QtCore import QRectF, QPointF
            pos = event.pos()
            clicked_table = None
            for t in tables:
                r = layout.frameBoundingRect(t)
                vr = QRectF(r.left(), r.top() - scrollbar_value, r.width(), r.height())
                margin = 8
                if vr.adjusted(-margin, -margin, margin, margin).contains(QPointF(pos)):
                    dist_left = abs(pos.x() - vr.left())
                    dist_right = abs(pos.x() - vr.right())
                    dist_top = abs(pos.y() - vr.top())
                    dist_bottom = abs(pos.y() - vr.bottom())
                    if min(dist_left, dist_right, dist_top, dist_bottom) <= margin:
                        clicked_table = t
                        break
            
            if clicked_table:
                start = clicked_table.firstPosition() - 1
                end = clicked_table.lastPosition() + 1
                new_cursor = QTextCursor(self.document())
                new_cursor.setPosition(start)
                new_cursor.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
                self.setTextCursor(new_cursor)
                
                self._dragging_table = clicked_table
                self._drag_start_pos = event.pos()
                event.accept()
                return

            # 2. 이미지 클릭 체크
            img_cursor, img_format = self.get_image_at_pos(event.pos())
            if img_cursor and img_format:
                self.setTextCursor(img_cursor)
                self.show_image_overlay(img_cursor, img_format)
                self._image_pressed = True
                self._press_pos = event.pos()
                super().mousePressEvent(event)
                return
                
        self._image_pressed = False
        self._dragging_table = None
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if getattr(self, "_dragging_table", None) is not None:
            self._dragging_table = None
            event.accept()
            return
            
        if getattr(self, "_image_pressed", False):
            self._image_pressed = False
            dist = (event.pos() - self._press_pos).manhattanLength()
            if dist < 4:
                img_cursor, img_format = self.get_image_at_pos(self._press_pos)
                if img_cursor and img_format:
                    self.setTextCursor(img_cursor)
                    self.show_image_overlay(img_cursor, img_format)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def mouseMoveEvent(self, event):
        # 표 드래그 앤 드롭 이동 처리
        if getattr(self, "_dragging_table", None) is not None:
            from PyQt6.QtWidgets import QApplication
            if (event.pos() - self._drag_start_pos).manhattanLength() >= QApplication.startDragDistance():
                from PyQt6.QtGui import QDrag
                from PyQt6.QtCore import QMimeData
                
                drag = QDrag(self)
                mime_data = QMimeData()
                
                cursor = self.textCursor()
                html = cursor.selection().toHtml()
                mime_data.setHtml(html)
                
                text = cursor.selection().toPlainText()
                mime_data.setText(text)
                
                drag.setMimeData(mime_data)
                self.viewport().setCursor(Qt.CursorShape.ClosedHandCursor)
                
                result = drag.exec(Qt.DropAction.MoveAction)
                if result == Qt.DropAction.MoveAction:
                    cursor.removeSelectedText()
                    
                self._dragging_table = None
                self.viewport().setCursor(Qt.CursorShape.IBeamCursor)
                event.accept()
                return

        img_cursor, img_format = self.get_image_at_pos(event.pos())
        if img_cursor and img_format:
            self.viewport().setCursor(Qt.CursorShape.OpenHandCursor)
            super().mouseMoveEvent(event)
            return

        # 마우스 호버 시 표 테두리 근처이면 커서를 PointingHand 모양으로 변경
        document = self.document()
        layout = document.documentLayout()
        scrollbar_value = self.verticalScrollBar().value()
        scrollbar_value_x = self.horizontalScrollBar().value()
        
        tables = []
        def find_tables(frame):
            for child in frame.childFrames():
                if isinstance(child, QTextTable):
                    tables.append(child)
                find_tables(child)
        find_tables(document.rootFrame())
        
        near_table_border = False
        from PyQt6.QtCore import QRectF, QPointF
        pos = event.pos()
        for t in tables:
            r = layout.frameBoundingRect(t)
            vr = QRectF(r.left() - scrollbar_value_x, r.top() - scrollbar_value, r.width(), r.height())
            margin = 8
            if vr.adjusted(-margin, -margin, margin, margin).contains(QPointF(pos)):
                dist_left = abs(pos.x() - vr.left())
                dist_right = abs(pos.x() - vr.right())
                dist_top = abs(pos.y() - vr.top())
                dist_bottom = abs(pos.y() - vr.bottom())
                if min(dist_left, dist_right, dist_top, dist_bottom) <= margin:
                    near_table_border = True
                    break
        
        if near_table_border:
            self.viewport().setCursor(Qt.CursorShape.PointingHandCursor)
        else:
            self.viewport().setCursor(Qt.CursorShape.IBeamCursor)
            
        super().mouseMoveEvent(event)

    def insertFromMimeData(self, source):
        # 1. Handle clipboard raw image (from screen capture / Snipping Tool)
        if source.hasImage():
            image = source.imageData()
            if isinstance(image, QImage) and not image.isNull():
                p = self.parent()
                while p:
                    if hasattr(p, "paste_image_action"):
                        if p.paste_image_action(image):
                            return
                        break
                    p = p.parent()
                
                # Fallback to inline Base64 if parent tab widget not found
                byte_array = QByteArray()
                buffer = QBuffer(byte_array)
                buffer.open(QIODevice.OpenModeFlag.WriteOnly)
                image.save(buffer, "PNG")
                base64_data = byte_array.toBase64().data().decode("utf-8")
                w_val, h_val = image.width(), image.height()
                self.insertHtml(f'<br><img src="data:image/png;base64,{base64_data}" width="{w_val}" height="{h_val}" /><br>')
                return

        # 2. Handle clipboard copied files (when user copies an image file from Windows Explorer)
        if source.hasUrls():
            has_inserted_image = False
            for url in source.urls():
                file_path = url.toLocalFile()
                if os.path.exists(file_path):
                    ext = os.path.splitext(file_path)[1].lower()
                    if ext in ['.png', '.jpg', '.jpeg', '.gif', '.bmp']:
                        p = self.parent()
                        while p:
                            if hasattr(p, "task_attachments_dir"):
                                file_name = os.path.basename(file_path)
                                dest_path = os.path.join(p.task_attachments_dir, file_name)
                                # Avoid duplicate names
                                base, e = os.path.splitext(file_name)
                                counter = 1
                                while os.path.exists(dest_path):
                                    file_name = f"{base}_{counter}{e}"
                                    dest_path = os.path.join(p.task_attachments_dir, file_name)
                                    counter += 1
                                try:
                                    shutil.copy2(file_path, dest_path)
                                    rel_path = f"attachments/task_{p.task_id}/{file_name}"
                                    img = QImage(dest_path)
                                    if not img.isNull():
                                        w_val, h_val = img.width(), img.height()
                                        self.insertHtml(f'<br><img src="{rel_path}" width="{w_val}" height="{h_val}" /><br>')
                                    else:
                                        self.insertHtml(f'<br><img src="{rel_path}" max-width="100%" /><br>')
                                    file_size = os.path.getsize(dest_path)
                                    att_id = p.db_mgr.add_task_attachment(p.task_id, rel_path, file_name, file_size, is_embed=1)
                                    if hasattr(p, 'track_added_attachment'):
                                        p.track_added_attachment(att_id, rel_path)
                                    p.load_attachments()
                                    has_inserted_image = True
                                except Exception as err:
                                    print(f"[Clipboard Image File Copy Error] {str(err)}")
                                break
                            p = p.parent()
            if has_inserted_image:
                return

        super().insertFromMimeData(source)

    def mouseDoubleClickEvent(self, event):
        pos = event.pos()
        
        # Check if double-clicked near a table border
        document = self.document()
        layout = document.documentLayout()
        scrollbar_value = self.verticalScrollBar().value()
        scrollbar_value_x = self.horizontalScrollBar().value()
        
        tables = []
        def find_tables(frame):
            for child in frame.childFrames():
                if isinstance(child, QTextTable):
                    tables.append(child)
                find_tables(child)
        find_tables(document.rootFrame())
        
        double_clicked_table = None
        from PyQt6.QtCore import QRectF, QPointF
        for t in tables:
            r = layout.frameBoundingRect(t)
            vr = QRectF(r.left() - scrollbar_value_x, r.top() - scrollbar_value, r.width(), r.height())
            margin = 8
            if vr.adjusted(-margin, -margin, margin, margin).contains(QPointF(pos)):
                dist_left = abs(pos.x() - vr.left())
                dist_right = abs(pos.x() - vr.right())
                dist_top = abs(pos.y() - vr.top())
                dist_bottom = abs(pos.y() - vr.bottom())
                if min(dist_left, dist_right, dist_top, dist_bottom) <= margin:
                    double_clicked_table = t
                    break
                    
        if double_clicked_table:
            self.show_table_overlay(double_clicked_table)
            self.table_overlay.selected_as_object = True
            self.table_overlay.update_geometry()
            self.table_overlay.update()
            event.accept()
            return

        cursor = self.cursorForPosition(pos)
        
        # Check character just before the cursor position
        helper_cursor = QTextCursor(self.document())
        helper_cursor.setPosition(cursor.position())
        helper_cursor.movePosition(QTextCursor.MoveOperation.PreviousCharacter, QTextCursor.MoveMode.KeepAnchor)
        
        image_format = None
        target_cursor = None
        
        if helper_cursor.charFormat().isImageFormat():
            image_format = helper_cursor.charFormat().toImageFormat()
            target_cursor = helper_cursor
        else:
            # Check character just after the cursor position
            helper_cursor.setPosition(cursor.position())
            helper_cursor.movePosition(QTextCursor.MoveOperation.NextCharacter, QTextCursor.MoveMode.KeepAnchor)
            if helper_cursor.charFormat().isImageFormat():
                image_format = helper_cursor.charFormat().toImageFormat()
                target_cursor = helper_cursor
                
        if image_format and target_cursor:
            self.setTextCursor(target_cursor)
            self.open_image_resize_dialog(target_cursor, image_format)
            return
            
        super().mouseDoubleClickEvent(event)

    def open_image_resize_dialog(self, cursor, image_format):
        current_width = image_format.width()
        current_height = image_format.height()
        img_name = image_format.name()
        
        if current_width <= 0 or current_height <= 0:
            original_size = self.get_image_original_size(img_name)
            if original_size:
                current_width, current_height = original_size.width(), original_size.height()
            else:
                current_width, current_height = 400, 300
                
        dialog = ImageResizeDialog(current_width, current_height, self)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            new_width, new_height = dialog.get_size()
            
            new_format = QTextImageFormat()
            new_format.setName(image_format.name())
            new_format.setWidth(new_width)
            new_format.setHeight(new_height)
            
            cursor.setCharFormat(new_format)

    def get_image_original_size(self, img_name):
        if img_name.startswith("data:image"):
            try:
                parts = img_name.split(",")
                if len(parts) > 1:
                    ba = QByteArray.fromBase64(parts[1].encode("utf-8"))
                    img = QImage.fromData(ba)
                    if not img.isNull():
                        return img.size()
            except Exception as e:
                print(f"Error parsing base64 size: {e}")
        else:
            full_path = os.path.normpath(os.path.join(base_dir, img_name))
            if os.path.exists(full_path):
                img = QImage(full_path)
                if not img.isNull():
                    return img.size()
        return None

    def contextMenuEvent(self, event):
        menu = self.createStandardContextMenu(event.pos())
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            menu.addSeparator()
            table_menu = menu.addMenu("표 (Table)")
            
            # Select table
            act_select = table_menu.addAction("표 전체 선택")
            act_select.triggered.connect(self.select_entire_table)
            
            # Delete table
            act_delete = table_menu.addAction("표 삭제")
            act_delete.triggered.connect(self.delete_current_table)
            
            table_menu.addSeparator()
            
            # Merge cells
            act_merge = table_menu.addAction("선택된 셀 병합")
            act_merge.triggered.connect(self.merge_selected_cells)
            
            # Split cell
            act_split = table_menu.addAction("셀 분할")
            act_split.triggered.connect(self.split_selected_cell)
            
            table_menu.addSeparator()
            
            # Insertions/Deletions
            act_ins_row_above = table_menu.addAction("위에 행 추가")
            act_ins_row_above.triggered.connect(self.insert_row_above)
            
            # Insert Row Below
            act_ins_row_below = table_menu.addAction("아래에 행 추가")
            act_ins_row_below.triggered.connect(self.insert_row_below)
            
            # Insert Column Left
            act_ins_col_left = table_menu.addAction("왼쪽에 열 추가")
            act_ins_col_left.triggered.connect(self.insert_column_left)
            
            # Insert Column Right
            act_ins_col_right = table_menu.addAction("오른쪽에 열 추가")
            act_ins_col_right.triggered.connect(self.insert_column_right)
            
            table_menu.addSeparator()
            
            # Delete Row
            act_del_row = table_menu.addAction("행 삭제")
            act_del_row.triggered.connect(self.delete_current_row)
            
            # Delete Column
            act_del_col = table_menu.addAction("열 삭제")
            act_del_col.triggered.connect(self.delete_current_column)
            
            table_menu.addSeparator()
            
            # Table properties
            act_props = table_menu.addAction("표 속성 변경...")
            act_props.triggered.connect(self.open_table_properties_dialog)
            
        menu.exec(event.globalPos())

    def select_entire_table(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            start = table.firstPosition() - 1
            end = table.lastPosition() + 1
            new_cursor = QTextCursor(self.document())
            new_cursor.setPosition(start)
            new_cursor.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
            self.setTextCursor(new_cursor)

    def delete_current_table(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            self.select_entire_table()
            self.textCursor().removeSelectedText()

    def merge_selected_cells(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            table.mergeCells(cursor)

    def split_selected_cell(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            row = cell.row()
            col = cell.column()
            table.splitCell(row, col, 1, 1)

    def insert_row_above(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            table.insertRows(cell.row(), 1)

    def insert_row_below(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            table.insertRows(cell.row() + 1, 1)

    def insert_column_left(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            table.insertColumns(cell.column(), 1)

    def insert_column_right(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            table.insertColumns(cell.column() + 1, 1)

    def delete_current_row(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            table.removeRows(cell.row(), 1)

    def delete_current_column(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if table:
            cell = table.cellAt(cursor)
            table.removeColumns(cell.column(), 1)

    def open_table_properties_dialog(self):
        cursor = self.textCursor()
        table = cursor.currentTable()
        if not table:
            return
        
        fmt = table.format()
        w_len = fmt.width()
        w_val = w_len.rawValue()
        w_type = w_len.type()
        
        border_brush = fmt.borderBrush()
        border_col = border_brush.color() if border_brush else QColor("#475569")
        
        bg_brush = fmt.background()
        bg_col = bg_brush.color() if bg_brush else QColor("#FFFFFF")
        
        dialog = TablePropertiesDialog(w_val, w_type, border_col, bg_col, self)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            new_w_val, new_w_type, new_border_col, new_bg_col = dialog.get_properties()
            
            from PyQt6.QtGui import QTextLength, QBrush
            fmt.setWidth(QTextLength(new_w_type, new_w_val))
            fmt.setBorderBrush(QBrush(new_border_col))
            fmt.setBackground(QBrush(new_bg_col))
            
            table.setFormat(fmt)
            
            # Apply background to every cell as well
            for row in range(table.rows()):
                for col in range(table.columns()):
                    cell = table.cellAt(row, col)
                    cell_fmt = cell.format()
                    cell_fmt.setBackground(QBrush(new_bg_col))
                    cell.setFormat(cell_fmt)


class RichTextEditor(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(2)

        # 툴바 생성
        self.toolbar = QWidget()
