    def show_search_panel(self):
        self.search_panel.show()
        self.txt_find.setFocus()
        self.txt_find.selectAll()
        if self.txt_find.text():
            self.on_find_text_changed(self.txt_find.text())

    def hide_search_panel(self):
        self.search_panel.hide()
        self.clear_search_highlights()
        self.text_edit.setFocus()

    def handle_escape_pressed(self):
        if self.search_panel.isVisible():
            self.hide_search_panel()

    def on_find_text_changed(self, text):
        self.current_match_idx = -1
        self.perform_search(text, move_cursor=True)

    def perform_search(self, text, move_cursor=True):
        if not text:
            self.clear_search_highlights()
            self.lbl_match_count.setText("")
            return

        doc = self.text_edit.document()
        match_cursors = []
        search_cursor = doc.find(text, 0)
        while not search_cursor.isNull():
            match_cursors.append(QTextCursor(search_cursor))
            search_cursor = doc.find(text, search_cursor)

        if not match_cursors:
            self.lbl_match_count.setText("결과 없음")
            self.text_edit.setExtraSelections([])
            self.current_match_idx = -1
            return

        current_pos = self.text_edit.textCursor().position()
        if self.current_match_idx < 0 or self.current_match_idx >= len(match_cursors):
            self.current_match_idx = 0
            for idx, mc in enumerate(match_cursors):
                if mc.selectionStart() >= current_pos:
                    self.current_match_idx = idx
                    break

        self.update_search_highlights(match_cursors)

    def find_next(self):
        text = self.txt_find.text()
        if not text:
            return
        doc = self.text_edit.document()
        match_cursors = []
        search_cursor = doc.find(text, 0)
        while not search_cursor.isNull():
            match_cursors.append(QTextCursor(search_cursor))
            search_cursor = doc.find(text, search_cursor)

        if not match_cursors:
            return

        self.current_match_idx = (self.current_match_idx + 1) % len(match_cursors)
        self.update_search_highlights(match_cursors)

    def find_prev(self):
        text = self.txt_find.text()
        if not text:
            return
        doc = self.text_edit.document()
        match_cursors = []
        search_cursor = doc.find(text, 0)
        while not search_cursor.isNull():
            match_cursors.append(QTextCursor(search_cursor))
            search_cursor = doc.find(text, search_cursor)

        if not match_cursors:
            return

        self.current_match_idx = (self.current_match_idx - 1) % len(match_cursors)
        self.update_search_highlights(match_cursors)

    def update_search_highlights(self, match_cursors):
        selections = []
        for i, mc in enumerate(match_cursors):
            selection = QTextEdit.ExtraSelection()
            selection.cursor = mc
            fmt = QTextCharFormat()
            if i == self.current_match_idx:
                fmt.setBackground(QColor("#F97316"))
                fmt.setForeground(QColor("#FFFFFF"))
            else:
                fmt.setBackground(QColor("#FEF08A"))
            selection.format = fmt
            selections.append(selection)

        self.text_edit.setExtraSelections(selections)
        if 0 <= self.current_match_idx < len(match_cursors):
            self.text_edit.setTextCursor(match_cursors[self.current_match_idx])
            self.text_edit.ensureCursorVisible()
        self.lbl_match_count.setText(f"{self.current_match_idx + 1}/{len(match_cursors)}")

    def clear_search_highlights(self):
        self.text_edit.setExtraSelections([])
        self.current_match_idx = -1

    def toggle_bold(self):
        weight = 700 if self.btn_bold.isChecked() else 400
        self.text_edit.setFontWeight(weight)

    def toggle_italic(self):
        self.text_edit.setFontItalic(self.btn_italic.isChecked())

    def toggle_underline(self):
        self.text_edit.setFontUnderline(self.btn_underline.isChecked())

    def choose_color(self):
        from PyQt6.QtWidgets import QColorDialog
        color = QColorDialog.getColor(self.text_edit.textColor(), self, "글자 색상 선택")
        if color.isValid():
            self.text_edit.setTextColor(color)

    def change_font_size(self, size_str):
        self.text_edit.setFontPointSize(float(size_str))

    def insert_image_flow(self):
        # Find detail tab parent widget to trigger file copy and image insert
        p = self.parent()
        while p:
            if hasattr(p, "insert_image_action"):
                p.insert_image_action()
                break
            p = p.parent()

    @staticmethod
    def _spin_arrow_png(up):
        """스핀박스용 삼각형 화살표 PNG를 임시 폴더에 생성하고 경로 반환.
        (QSS 화살표는 image: 속성으로만 그릴 수 있음 — CSS border 삼각형 미지원)"""
        import tempfile
        from PyQt6.QtGui import QImage, QPainter, QColor, QPolygon
        from PyQt6.QtCore import QPoint
        path = os.path.join(tempfile.gettempdir(), f"bga_spin_{'up' if up else 'down'}.png")
        if not os.path.exists(path):
            img = QImage(7, 4, QImage.Format.Format_ARGB32)
            img.fill(Qt.GlobalColor.transparent)
            p = QPainter(img)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#475569"))
            if up:
                pts = [QPoint(0, 4), QPoint(7, 4), QPoint(3, 0)]
            else:
                pts = [QPoint(0, 0), QPoint(7, 0), QPoint(3, 4)]
            p.drawPolygon(QPolygon(pts))
            p.end()
            img.save(path)
        return path.replace("\\", "/")

    def insert_table_flow(self):
        from PyQt6.QtWidgets import QDialog, QFormLayout, QSpinBox, QDialogButtonBox
        dialog = QDialog(self)
        dialog.setWindowTitle("표 삽입")
        dialog.setMinimumWidth(220)
        up_png = self._spin_arrow_png(True)
        down_png = self._spin_arrow_png(False)
        dialog.setStyleSheet("""
            QDialog {
                background-color: #FFFFFF;
                border-radius: 8px;
            }
            QLabel {
                font-size: 12px;
                color: #334155;
                font-family: 'Malgun Gothic', sans-serif;
            }
            QSpinBox {
                border: 1px solid #CBD5E1;
                border-radius: 4px;
                padding: 4px;
                padding-right: 24px;
                min-width: 60px;
                font-size: 12px;
            }
            QSpinBox::up-button {
                subcontrol-origin: border;
                subcontrol-position: top right;
                width: 20px;
                height: 13px;
                border-left: 1px solid #CBD5E1;
                border-bottom: 1px solid #CBD5E1;
                border-top-right-radius: 4px;
                background: #F8FAFC;
            }
            QSpinBox::down-button {
                subcontrol-origin: border;
                subcontrol-position: bottom right;
                width: 20px;
                height: 13px;
                border-left: 1px solid #CBD5E1;
                border-bottom-right-radius: 4px;
                background: #F8FAFC;
            }
            QSpinBox::up-button:hover, QSpinBox::down-button:hover {
                background: #E2E8F0;
            }
            QPushButton {
                background-color: #3B82F6;
                color: white;
                border: none;
                border-radius: 4px;
                padding: 6px 12px;
                font-weight: bold;
                font-size: 12px;
            }
            QPushButton:hover {
                background-color: #2563EB;
            }
        """ + f"""
            QSpinBox::up-arrow {{
                image: url({up_png});
                width: 7px; height: 4px;
            }}
            QSpinBox::down-arrow {{
                image: url({down_png});
                width: 7px; height: 4px;
            }}
        """)
        
        layout = QFormLayout(dialog)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)
        
        spin_rows = QSpinBox(dialog)
        spin_rows.setRange(1, 50)
        spin_rows.setValue(3)
        
        spin_cols = QSpinBox(dialog)
        spin_cols.setRange(1, 50)
        spin_cols.setValue(3)
        
        layout.addRow("행 개수 (Rows):", spin_rows)
        layout.addRow("열 개수 (Columns):", spin_cols)
        
        # Add custom buttons
        button_box = QDialogButtonBox(dialog)
        btn_ok = button_box.addButton("확인", QDialogButtonBox.ButtonRole.AcceptRole)
        btn_cancel = button_box.addButton("취소", QDialogButtonBox.ButtonRole.RejectRole)
        
        # Apply standard stylesheet to cancel button
        btn_cancel.setStyleSheet("""
            QPushButton {
                background-color: #F1F5F9;
                color: #475569;
                border: 1px solid #CBD5E1;
            }
            QPushButton:hover {
                background-color: #E2E8F0;
            }
        """)
        
        button_box.accepted.connect(dialog.accept)
        button_box.rejected.connect(dialog.reject)
        layout.addRow(button_box)
        
        if dialog.exec() == QDialog.DialogCode.Accepted:
            rows = spin_rows.value()
            cols = spin_cols.value()
            
            cursor = self.text_edit.textCursor()
            from PyQt6.QtGui import QTextTableFormat, QTextLength, QBrush, QColor
            table_format = QTextTableFormat()
            table_format.setCellPadding(8)
            table_format.setCellSpacing(0)
            table_format.setBorder(1)
            table_format.setBorderBrush(QBrush(QColor("#475569")))  # slate 600
            table_format.setWidth(QTextLength(QTextLength.Type.PercentageLength, 50))  # 50% width
            # Initialize equal column width constraints
            constraints = [QTextLength(QTextLength.Type.PercentageLength, 100.0 / cols)] * cols
            table_format.setColumnWidthConstraints(constraints)
            
            cursor.beginEditBlock()
            try:
                table = cursor.insertTable(rows, cols, table_format)
                
                # 개별 셀에도 흰색 배경 적용하여 에디터 가이드라인 비침 차단
                for r_idx in range(table.rows()):
                    for c_idx in range(table.columns()):
                        cell = table.cellAt(r_idx, c_idx)
                        cell_fmt = cell.format()
                        cell_fmt.setBackground(QBrush(QColor("#FFFFFF")))
                        cell.setFormat(cell_fmt)
            finally:
                cursor.endEditBlock()

    def update_toolbar_states(self, fmt):
        self.btn_bold.blockSignals(True)
        self.btn_bold.setChecked(fmt.fontWeight() == 700)
        self.btn_bold.blockSignals(False)

        self.btn_italic.blockSignals(True)
        self.btn_italic.setChecked(fmt.fontItalic())
        self.btn_italic.blockSignals(False)

        self.btn_underline.blockSignals(True)
        self.btn_underline.setChecked(fmt.fontUnderline())
        self.btn_underline.blockSignals(False)

        self.combo_size.blockSignals(True)
        size = fmt.fontPointSize()
        if size > 0:
            self.combo_size.setCurrentText(str(int(size)))
        self.combo_size.blockSignals(False)



