# 반복 일정 및 달력 연동 관련 헬퍼 함수 & 클래스 정의
# ==============================================================================
from datetime import datetime, date, timedelta
import calendar
from PyQt6.QtWidgets import (QCalendarWidget, QStackedWidget, QDateEdit, QSpinBox, 
                             QFrame, QListWidget, QListWidgetItem, QCheckBox)
from PyQt6.QtGui import QColor, QPainter, QCursor, QShortcut, QKeySequence

def get_last_day_of_month(any_date):
    return calendar.monthrange(any_date.year, any_date.month)[1]

def get_nth_weekday_of_month(year, month, nth, weekday):
    c = calendar.Calendar(firstweekday=0)
    month_cal = c.monthdatescalendar(year, month)
    py_wday = weekday - 1
    matching_dates = []
    for week in month_cal:
        for d in week:
            if d.year == year and d.month == month and d.weekday() == py_wday:
                matching_dates.append(d)
    if nth == 'last':
        return matching_dates[-1] if matching_dates else None
    else:
        try:
            n = int(nth)
            return matching_dates[n-1] if len(matching_dates) >= n else None
        except:
            return None

def is_task_scheduled_on_date(doc, target_date):
    if not doc.get('is_repeating'):
        return False
    if doc.get('has_period'):
        if doc.get('start_date'):
            try:
                start = datetime.strptime(doc['start_date'][:10], "%Y-%m-%d").date()
                if target_date < start:
                    return False
            except:
                pass
        if doc.get('end_date'):
            try:
                end = datetime.strptime(doc['end_date'][:10], "%Y-%m-%d").date()
                if target_date > end:
                    return False
            except:
                pass
    rec_type = doc.get('recurrence_type')
    val = doc.get('recurrence_value') or ""
    if rec_type == 'daily_interval':
        try:
            interval = int(val)
            base_date_str = doc.get('start_date') or doc.get('created_at') or "2026-01-01"
            base_date = datetime.strptime(base_date_str[:10], "%Y-%m-%d").date()
            days_diff = (target_date - base_date).days
            return days_diff >= 0 and (days_diff % interval) == 0
        except:
            return False
    elif rec_type == 'monthly_day':
        if val == "last":
            last_day = get_last_day_of_month(target_date)
            return target_date.day == last_day
        else:
            try:
                day_num = int(val)
                return target_date.day == day_num
            except:
                return False
    elif rec_type == 'monthly_nth_weekday':
        if "|" in val:
            try:
                nth, wday_str = val.split("|", 1)
                wday = int(wday_str)
                scheduled_date = get_nth_weekday_of_month(target_date.year, target_date.month, nth, wday)
                return scheduled_date == target_date
            except:
                return False
        return False
    elif rec_type == 'weekly_interval':
        if "|" in val:
            try:
                interval_str, days_str = val.split("|", 1)
                interval = int(interval_str)
                active_days = [int(d) for d in days_str.split(",") if d]
            except:
                return False
        else:
            try:
                interval = int(val)
                active_days = []
            except:
                return False
        target_wday = target_date.isoweekday()
        if active_days and target_wday not in active_days:
            return False
        base_date_str = doc.get('start_date') or doc.get('created_at') or "2026-01-01"
        try:
            base_date = datetime.strptime(base_date_str[:10], "%Y-%m-%d").date()
        except:
            base_date = date(2026, 1, 1)
        base_monday = base_date - timedelta(days=base_date.weekday())
        target_monday = target_date - timedelta(days=target_date.weekday())
        days_diff = (target_monday - base_monday).days
        weeks_diff = days_diff // 7
        return weeks_diff >= 0 and (weeks_diff % interval) == 0
    elif rec_type == 'yearly':
        if "|" in val:
            try:
                m_str, d_str = val.split("|", 1)
                m = int(m_str)
                d = int(d_str)
                return target_date.month == m and target_date.day == d
            except:
                return False
    return False

def get_recurrence_description(rec_type, rec_val):
    if not rec_type:
        return ""
    val = rec_val or ""
    if rec_type == 'daily_interval':
        return f"{val}일마다 반복"
    elif rec_type == 'monthly_day':
        if val == "last":
            return "매월 말일"
        return f"매월 {val}일"
    elif rec_type == 'monthly_nth_weekday':
        if "|" in val:
            nth, wday_str = val.split("|", 1)
            wday_names = ["월요일", "화요일", "수요일", "목요일", "금요일", "토요일", "일요일"]
            try:
                wday_num = int(wday_str)
                wday_name = wday_names[wday_num - 1]
            except:
                wday_name = ""
            nth_name = {"1": "첫째주", "2": "둘째주", "3": "셋째주", "4": "넷째주", "last": "마지막주"}.get(nth, nth)
            return f"매월 {nth_name} {wday_name}"
        return "매월 요일지정"
    elif rec_type == 'weekly_interval':
        if "|" in val:
            interval, days_str = val.split("|", 1)
            wday_short = {7: "일", 1: "월", 2: "화", 3: "수", 4: "목", 5: "금", 6: "토"}
            active = []
            for d in days_str.split(","):
                try:
                    num = int(d)
                    active.append(wday_short[num])
                except:
                    pass
            days_desc = f" ({','.join(active)})" if active else ""
            return f"{interval}주마다{days_desc}"
        else:
            return f"{val}주마다"
    elif rec_type == 'yearly':
        if "|" in val:
            m, d = val.split("|", 1)
            return f"매년 {m}월 {d}일"
    return ""

class HighlightedCalendar(QCalendarWidget):
    def __init__(self, db_mgr, parent=None):
        super().__init__(parent)
        self.db_mgr = db_mgr
        self.repeating_tasks = []
        self.load_all_repeating_tasks()
        
    def load_all_repeating_tasks(self):
        try:
            all_tasks = self.db_mgr.get_all_task_documents()
            self.repeating_tasks = [t for t in all_tasks if t.get('is_repeating')]
        except Exception as e:
            print(f"Error loading repeating tasks: {e}")
            self.repeating_tasks = []
        
    def paintCell(self, painter, rect, date):
        super().paintCell(painter, rect, date)
        try:
            py_date = date.toPyDate()
            task_count = 0
            for doc in self.repeating_tasks:
                try:
                    if is_task_scheduled_on_date(doc, py_date):
                        task_count += 1
                except Exception as ex:
                    print(f"Error checking schedule for task {doc.get('id')}: {ex}")
                    
            if task_count > 0:
                painter.save()
                painter.setRenderHint(QPainter.RenderHint.Antialiasing)
                
                # Draw the "+n" text at the bottom center of the cell
                text_rect = QRect(rect.left(), rect.bottom() - 18, rect.width(), 14)
                
                painter.setPen(QColor("#0284C7"))
                font = painter.font()
                font.setPointSize(8)
                font.setBold(True)
                painter.setFont(font)
                painter.drawText(text_rect, Qt.AlignmentFlag.AlignCenter, f"+{task_count}")
                
                painter.restore()
        except Exception as e:
            print(f"Error in HighlightedCalendar.paintCell: {e}")

