    def go_to_today(self):
        today = QDate.currentDate()
        self.calendar.setSelectedDate(today)
        self.on_date_clicked(today)

    def refresh_calendar(self):
        self.calendar.load_all_repeating_tasks()
        self.calendar.updateCells()
        self.on_date_clicked(self.calendar.selectedDate())

    def on_date_clicked(self, qdate):
        py_date = qdate.toPyDate()
        wday_names = ["월요일", "화요일", "수요일", "목요일", "금요일", "토요일", "일요일"]
        wday_name = wday_names[py_date.weekday()]
        self.lbl_selected_date.setText(f"📅 {py_date.strftime('%Y년 %m월 %d일')} ({wday_name})")
        
        self.list_tasks.clear()
        
        scheduled_tasks = []
        for doc in self.calendar.repeating_tasks:
            if is_task_scheduled_on_date(doc, py_date):
                scheduled_tasks.append(doc)
                
        if not scheduled_tasks:
            item = QListWidgetItem("이 날짜에 계획된 반복 업무가 없습니다.")
            item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsSelectable)
            item.setForeground(QColor("#94A3B8"))
            self.list_tasks.addItem(item)
            self.btn_view_task.setEnabled(False)
        else:
            for doc in scheduled_tasks:
                desc = get_recurrence_description(doc.get('recurrence_type'), doc.get('recurrence_value'))
                item = QListWidgetItem()
                item.setData(Qt.ItemDataRole.UserRole, doc['id'])
                item.setSizeHint(QSize(0, 32))
                self.list_tasks.addItem(item)
                
                lbl = QLabel()
                lbl.setText(f"📄 <span style='color: #0F172A; font-weight: bold;'>{doc['title']}</span> &nbsp;&nbsp;<span style='color: #0284C7; font-weight: normal; font-size: 11px;'>[{desc}]</span>")
                lbl.setStyleSheet("background: transparent; border: none; padding-left: 4px;")
                lbl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
                self.list_tasks.setItemWidget(item, lbl)
            self.btn_view_task.setEnabled(True)

    def on_task_double_clicked(self, item):
        task_id = item.data(Qt.ItemDataRole.UserRole)
        if task_id:
            self.main_win.open_task_detail_tab(task_id)

    def on_view_task_clicked(self):
        selected_items = self.list_tasks.selectedItems()
        if selected_items:
            self.on_task_double_clicked(selected_items[0])

    def show_context_menu(self, pos):
        item = self.list_tasks.itemAt(pos)
        if not item:
            return
        task_id = item.data(Qt.ItemDataRole.UserRole)
        if not task_id:
            return
            
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #FFFFFF;
                border: 1px solid #E2E8F0;
                border-radius: 6px;
                padding: 4px;
            }
            QMenu::item {
                padding: 6px 20px;
                border-radius: 4px;
                color: #1E293B;
                font-size: 11px;
            }
            QMenu::item:selected {
                background-color: #EFF6FF;
                color: #2563EB;
            }
        """)
        
        edit_action = menu.addAction("🔄 반복주기 수정")
        action = menu.exec(self.list_tasks.mapToGlobal(pos))
        
        if action == edit_action:
            doc = self.db_mgr.get_task_document_by_id(task_id)
            if not doc:
                return
            
            is_rep = doc.get('is_repeating', 0)
            rec_type = doc.get('recurrence_type')
            rec_value = doc.get('recurrence_value')
            has_period = doc.get('has_period', 0)
            start_date = doc.get('start_date')
            end_date = doc.get('end_date')
            
            dialog = RecurrenceSettingsDialog(is_rep, rec_type, rec_value, has_period, start_date, end_date, self)
            if dialog.exec() == QDialog.DialogCode.Accepted:
                new_is_repeating, new_rec_type, new_rec_value, new_has_period, new_start_date, new_end_date = dialog.get_data()
                self.db_mgr.update_task_document(
                    doc_id=task_id,
                    title=doc['title'],
                    content=doc['content'],
                    cat_id=doc['category_id'],
                    is_repeating=new_is_repeating,
                    recurrence_type=new_rec_type,
                    recurrence_value=new_rec_value,
                    has_period=new_has_period,
                    start_date=new_start_date,
                    end_date=new_end_date
                )
                self.refresh_calendar()
                
                # Update open tab if exists
                if hasattr(self.main_win, "open_task_tabs"):
                    tab_key = ("task", task_id)
                    if tab_key in self.main_win.open_task_tabs:
                        self.main_win.open_task_tabs[tab_key].load_task_data()
                
                if hasattr(self.main_win, "task_info_sidebar") and self.main_win.task_info_sidebar:
                    self.main_win.task_info_sidebar.refresh_tree()

