    def update_table_category(self, table_name, category_name, old_category=None):
        with self.get_connection() as conn:
            cursor = conn.cursor()
            if old_category:
                cursor.execute(
                    "UPDATE table_categories SET task_category = ? WHERE table_name = ? AND task_category = ?",
                    (category_name, table_name, old_category)
                )
            else:
                cursor.execute(
                    "SELECT COUNT(*) FROM table_categories WHERE table_name = ? AND task_category = ?",
                    (table_name, category_name)
                )
                if cursor.fetchone()[0] == 0:
                    cursor.execute(
                        "INSERT INTO table_categories (table_name, task_category, task_order) VALUES (?, ?, 999999)",
                        (table_name, category_name)
                    )
            conn.commit()

    def rename_task_category(self, old_name, new_name):
        with self.get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT table_name, task_category, task_order FROM table_categories")
            rows = cursor.fetchall()
            for r in rows:
                cat = r['task_category']
                if cat == old_name:
                    cursor.execute(
                        "UPDATE table_categories SET task_category = ? WHERE table_name = ? AND task_category = ?",
                        (new_name, r['table_name'], cat)
                    )
                elif cat.startswith(old_name + "/"):
                    new_cat = new_name + cat[len(old_name):]
                    cursor.execute(
                        "UPDATE table_categories SET task_category = ? WHERE table_name = ? AND task_category = ?",
                        (new_cat, r['table_name'], cat)
                    )
            conn.commit()

