    def save_table_tree_order_and_categories(self, updates):
        with self.get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("DELETE FROM table_categories")
            seen = set()
            for row in updates:
                if len(row) == 3:
                    table_name, cat_path, order_idx = row
                    display_name = None
                    joins_json = None
                else:
                    table_name, cat_path, order_idx, display_name, joins_json = row
                
                key = (table_name, cat_path, display_name, joins_json)
                if key not in seen:
                    cursor.execute(
                        "INSERT INTO table_categories (table_name, task_category, task_order, display_name, joins_json) VALUES (?, ?, ?, ?, ?)",
                        (table_name, cat_path, order_idx, display_name, joins_json)
                    )
                    seen.add(key)
            conn.commit()

    def get_tables_list(self, search_keyword=None, search_type="테이블"):
        """테이블 목록 조회 (즐겨찾기 여부 최상단 배치 및 정렬, 구분 검색 지원)"""
        with self.get_connection() as conn:
            cursor = conn.cursor()
            if search_keyword and search_keyword.strip():
                like_keyword = f"%{search_keyword.strip()}%"
                if search_type == "컬럼":
                    # 컬럼 검색: EXISTS 절을 사용하여 조인을 효율적으로 수행하고 성능을 높임
                    cursor.execute("""
                    SELECT t.table_name, t.table_ko_name, t.is_favorite
                    FROM tables t
                    WHERE EXISTS (
                        SELECT 1 FROM columns c 
                        WHERE c.table_name = t.table_name 
                          AND (c.column_name LIKE ? OR c.column_ko_name LIKE ?)
                    )
                    ORDER BY t.is_favorite DESC, t.table_name ASC
                    """, (like_keyword, like_keyword))
                else:
                    # 테이블 검색: columns 테이블 조인 없이 tables 만 단독 조회하여 버벅임 완전 해결
                    cursor.execute("""
                    SELECT table_name, table_ko_name, is_favorite 
                    FROM tables 
                    WHERE table_name LIKE ? OR table_ko_name LIKE ?
                    ORDER BY is_favorite DESC, table_name ASC
                    """, (like_keyword, like_keyword))
            else:
                cursor.execute("""
                SELECT table_name, table_ko_name, is_favorite 
                FROM tables 
                ORDER BY is_favorite DESC, table_name ASC
                """)
            return [dict(row) for row in cursor.fetchall()]

    def search_tables_by_name(self, keyword):
        """관계 설정 팝업 내 테이블 영어/한글 검색용"""
        with self.get_connection() as conn:
            cursor = conn.cursor()
            if keyword and keyword.strip():
                lk = f"%{keyword.strip()}%"
                cursor.execute("""
                SELECT table_name, table_ko_name 
                FROM tables 
                WHERE table_name LIKE ? OR table_ko_name LIKE ?
                ORDER BY table_name ASC
                """, (lk, lk))
            else:
                cursor.execute("""
                SELECT table_name, table_ko_name 
                FROM tables 
                ORDER BY table_name ASC
                """)
            return [dict(row) for row in cursor.fetchall()]

    def toggle_favorite(self, table_name):
        """즐겨찾기 상태를 반전시킴"""
        with self.get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT is_favorite FROM tables WHERE table_name = ?", (table_name,))
            row = cursor.fetchone()
            if row:
                new_val = 1 if row['is_favorite'] == 0 else 0
                cursor.execute("UPDATE tables SET is_favorite = ? WHERE table_name = ?", (new_val, table_name))
                conn.commit()
                return new_val
            return 0

    def get_table_columns(self, table_name):
        """특정 테이블의 모든 컬럼 정보 및 매핑 관계를 조회"""
        with self.get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("""
            SELECT c.column_name, c.column_ko_name, c.data_type, c.length, c.is_nullable, c.is_pk,
                   c.is_selected, c.is_where,
                   r.ref_table_name, r.custom_query,
                   COALESCE(r.code_slot, 1) AS code_slot,
                   CASE 
                       WHEN r.custom_query IS NOT NULL AND r.custom_query != '' THEN '공통코드'
                       WHEN r.ref_table_name IS NOT NULL AND r.ref_table_name != '' AND EXISTS (
                           SELECT 1 FROM common_codes cc
                           WHERE cc.code_group_id = r.ref_table_name
                       ) THEN '공통코드'
                       WHEN r.ref_table_name IS NOT NULL AND r.ref_table_name != '' AND EXISTS (
                           SELECT 1 FROM tables t
                           WHERE t.table_name = r.ref_table_name
                       ) THEN '마스터테이블'
                       WHEN r.ref_table_name IS NOT NULL AND r.ref_table_name != '' THEN '마스터테이블'
                       ELSE NULL 
                   END AS mapping_type
            FROM columns c
            LEFT JOIN relations r 
              ON c.table_name = r.src_table_name AND c.column_name = r.src_column_name
            WHERE c.table_name = ?
            ORDER BY c.is_pk DESC, c.id ASC
            """, (table_name,))
            return [dict(row) for row in cursor.fetchall()]

