    def get_all_relations(self, search_keyword=None, search_type="본래테이블명"):
        with self.get_connection() as conn:
            cursor = conn.cursor()
            # 공통코드는 제외하고 마스터테이블 관계만 조회
            # SQLite 호환을 위해 서브쿼리 alias를 WHERE에 쓰지 않고 직접 NOT EXISTS로 필터링
            base_query = """
            SELECT r.src_table_name, r.src_column_name, r.ref_table_name,
                   '마스터테이블' AS mapping_type
            FROM relations r
            WHERE (r.custom_query IS NULL OR r.custom_query = '')
              AND NOT EXISTS (
                  SELECT 1 FROM common_codes cc2
                  WHERE cc2.code_group_id = r.ref_table_name
              )
            """
            if search_keyword and search_keyword.strip():
                lk = f"%{search_keyword.strip()}%"
                if search_type in ["참조테이블명", "참조테이블"]:
                    cursor.execute(base_query + " AND ref_table_name LIKE ? ORDER BY src_table_name ASC, src_column_name ASC", (lk,))
                elif search_type == "컬럼명":
                    cursor.execute(base_query + " AND src_column_name LIKE ? ORDER BY src_table_name ASC, src_column_name ASC", (lk,))
                else:  # "본래테이블명", "본래테이블"
                    cursor.execute(base_query + " AND src_table_name LIKE ? ORDER BY src_table_name ASC, src_column_name ASC", (lk,))
            else:
                cursor.execute(base_query + " ORDER BY src_table_name ASC, src_column_name ASC")
            return [dict(row) for row in cursor.fetchall()]

    def upsert_relation(self, src_table, src_column, ref_table, mapping_type, custom_query=None, code_slot=1):
        """수동으로 관계 정보를 등록하거나 수정함"""
        with self.get_connection() as conn:
            cursor = conn.cursor()
            # 기존에 동일한 컬럼에 맺어진 관계가 있는지 확인
            cursor.execute("""
            SELECT id FROM relations 
            WHERE src_table_name = ? AND src_column_name = ?
            """, (src_table, src_column))
            row = cursor.fetchone()
            
            if row:
                # 존재하면 기존 레코드를 UPDATE
                cursor.execute("""
                UPDATE relations 
                SET ref_table_name = ?, custom_query = ?, code_slot = ? 
                WHERE src_table_name = ? AND src_column_name = ?
                """, (ref_table, custom_query, code_slot, src_table, src_column))
            else:
                # 없으면 새롭게 INSERT
                cursor.execute("""
                INSERT INTO relations (src_table_name, src_column_name, ref_table_name, custom_query, code_slot)
                VALUES (?, ?, ?, ?, ?)
                """, (src_table, src_column, ref_table, custom_query, code_slot))
            conn.commit()

    def delete_relation(self, src_table, src_column):
        """기존 관계 정보를 삭제함"""
        with self.get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("""
            DELETE FROM relations 
            WHERE src_table_name = ? AND src_column_name = ?
            """, (src_table, src_column))
            conn.commit()

