    def update_task_document(self, doc_id, title, content, cat_id=None,
                             is_repeating=0, recurrence_type=None, recurrence_value=None,
                             has_period=0, start_date=None, end_date=None):
        """업무 문서 수정"""
        now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with self.get_connection() as conn:
            cursor = conn.cursor()
            if cat_id is not None:
                cursor.execute("""
                UPDATE task_documents 
                SET title = ?, content = ?, category_id = ?, updated_at = ?,
                    is_repeating = ?, recurrence_type = ?, recurrence_value = ?,
                    has_period = ?, start_date = ?, end_date = ?
                WHERE id = ?
                """, (title, content, cat_id, now_str,
                      is_repeating, recurrence_type, recurrence_value,
                      has_period, start_date, end_date, doc_id))
            else:
                cursor.execute("""
                UPDATE task_documents 
                SET title = ?, content = ?, updated_at = ?,
                    is_repeating = ?, recurrence_type = ?, recurrence_value = ?,
                    has_period = ?, start_date = ?, end_date = ?
                WHERE id = ?
                """, (title, content, now_str,
                      is_repeating, recurrence_type, recurrence_value,
                      has_period, start_date, end_date, doc_id))
            conn.commit()

