        with self.get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("""
            SELECT id, category_id, title, content, created_at, updated_at, is_favorite, sort_order,
                   is_repeating, recurrence_type, recurrence_value, has_period, start_date, end_date
            FROM task_documents 
            WHERE id = ?
            """, (doc_id,))
            row = cursor.fetchone()
            return dict(row) if row else None

