    # --- 업무별 테이블 로딩 및 검색 ---
    def load_tasks_tree(self, search_text=None, search_type="업무분류명"):
        self.tree_tasks.clear()
        self.tree_tasks.blockSignals(True)
        
        tables = self.db_mgr.get_tables_for_tree(search_text, search_type)
        
        root = {"subcats": {}, "tables": []}
        
        for t in tables:
            cat_path = t['task_category']
            if not cat_path or not cat_path.strip():
                continue
            
            parts = [p.strip() for p in cat_path.split('/') if p.strip()]
            if not parts:
                continue
                
            curr = root
            path_so_far = []
            for part in parts:
                path_so_far.append(part)
                full_path = "/".join(path_so_far)
                if part not in curr["subcats"]:
                    curr["subcats"][part] = {
                        "subcats": {},
                        "tables": [],
                        "name": part,
                        "full_path": full_path
                    }
                curr = curr["subcats"][part]
                
            curr["tables"].append(t)
            
        def add_node_to_tree(parent_item, node):
            def get_min_order(n):
                orders = [t['task_order'] for t in n['tables'] if t['task_order'] is not None]
                for sub in n['subcats'].values():
                    sub_min = get_min_order(sub)
                    if sub_min is not None:
                        orders.append(sub_min)
                return min(orders) if orders else 999999
            
            sorted_subcats = sorted(node["subcats"].values(), key=get_min_order)
            
            for sub in sorted_subcats:
                sub_item = QTreeWidgetItem(parent_item)
                sub_item.setText(0, f"📁 {sub['name']}")
                sub_item.setData(0, Qt.ItemDataRole.UserRole, {"type": "category", "name": sub['name'], "full_path": sub['full_path']})
                sub_item.setFont(0, QFont("Malgun Gothic", 9, QFont.Weight.Bold))
                sub_item.setForeground(0, QColor("#1E293B"))
                sub_item.setFlags(sub_item.flags() | Qt.ItemFlag.ItemIsDragEnabled | Qt.ItemFlag.ItemIsDropEnabled)
                
                add_node_to_tree(sub_item, sub)
                sub_item.setExpanded(True)
                
            for t in node["tables"]:
                t = dict(t)
                child_item = QTreeWidgetItem(parent_item)
                display_text = t['display_name'] if t.get('display_name') else t['table_name']
                if not t.get('display_name') and t['table_ko_name']:
                    display_text += f" ({t['table_ko_name']})"
                if t.get('joins_json'):
                    display_text = f"🔗 {display_text}"
                child_item.setText(0, display_text)
                child_item.setData(0, Qt.ItemDataRole.UserRole, {
                    "type": "table",
                    "id": t['id'],
                    "table_name": t['table_name'],
                    "table_ko_name": t['table_ko_name'],
                    "category_path": node.get("full_path", "기타"),
                    "display_name": t.get('display_name'),
                    "joins_json": t.get('joins_json')
                })
                child_item.setFont(0, QFont("Malgun Gothic", 9))
                child_item.setForeground(0, QColor("#475569"))
                child_item.setFlags(child_item.flags() | Qt.ItemFlag.ItemIsDragEnabled)
                
        add_node_to_tree(self.tree_tasks, root)
        self.tree_tasks.blockSignals(False)

    def do_task_search(self):
        search_type = self.combo_search_tasks_type.currentText()
        self.load_tasks_tree(self.txt_search_tasks.text(), search_type)

