    # --- 공통코드 사이드바 로딩 및 클릭 ---
    def load_codes_list(self, search_text=None, force_reload=False):
        if search_text is not None and not force_reload and self.list_codes.count() > 0:
            search_text_stripped = search_text.strip()
            self.list_codes.setUpdatesEnabled(False)
            if not search_text_stripped:
                for idx in range(self.list_codes.count()):
                    self.list_codes.item(idx).setHidden(False)
            else:
                search_type = "코드그룹"
                if hasattr(self, 'combo_search_type_codes'):
                    search_type = self.combo_search_type_codes.currentText()
                groups = self.db_mgr.get_unique_code_groups(search_text_stripped, search_type)
                matching_groups = {g['code_group'] for g in groups}
                
                for idx in range(self.list_codes.count()):
                    item = self.list_codes.item(idx)
                    grp_id = item.data(Qt.ItemDataRole.UserRole)
                    if grp_id:
                        item.setHidden(grp_id not in matching_groups)
            self.list_codes.setUpdatesEnabled(True)
            return

        self.list_codes.setUpdatesEnabled(False)
        self.list_codes.clear()
        
        search_type = "코드그룹"
        if hasattr(self, 'combo_search_type_codes'):
            search_type = self.combo_search_type_codes.currentText()
            
        groups = self.db_mgr.get_unique_code_groups(search_text, search_type)
        
        for grp in groups:
            grp_id = grp['code_group']
            ko_desc = grp['code_group_name'] or ""
            display_text = f"{grp_id} ({ko_desc})" if ko_desc else grp_id
            
            item = QListWidgetItem(self.list_codes)
            item.setText(display_text)
            item.setData(Qt.ItemDataRole.UserRole, grp_id)
            item.setSizeHint(QSize(100, 32))
            self.list_codes.addItem(item)
            
        self.list_codes.setUpdatesEnabled(True)

    def on_search_type_codes_changed(self, index):
        stype = self.combo_search_type_codes.currentText()
        if stype == "코드그룹":
            self.txt_search_codes.setPlaceholderText("코드그룹명 검색...")
        elif stype == "코드명":
            self.txt_search_codes.setPlaceholderText("코드명 검색...")
        else:
            self.txt_search_codes.setPlaceholderText("코드한글명 검색...")
        self.do_code_search() # 즉시 검색 실행

