    def load_relations_list(self, search_text=None, force_reload=False):
        if search_text is not None and not force_reload and self.list_relations.count() > 0:
            search_text_stripped = search_text.strip()
            self.list_relations.setUpdatesEnabled(False)
            if not search_text_stripped:
                for idx in range(self.list_relations.count()):
                    self.list_relations.item(idx).setHidden(False)
            else:
                search_type = "본래테이블"
                if hasattr(self, 'combo_search_type_relations'):
                    search_type = self.combo_search_type_relations.currentText()
                rels = self.db_mgr.get_all_relations(search_text_stripped, search_type)
                matching_descs = {f"{r['src_table_name']} ➔ {r['ref_table_name']}" for r in rels}
                
                for idx in range(self.list_relations.count()):
                    item = self.list_relations.item(idx)
                    rel_desc = item.data(Qt.ItemDataRole.UserRole)
                    if rel_desc:
                        item.setHidden(rel_desc not in matching_descs)
            self.list_relations.setUpdatesEnabled(True)
            return

        self.list_relations.setUpdatesEnabled(False)
        self.list_relations.clear()
        
        search_type = "본래테이블"
        if hasattr(self, 'combo_search_type_relations'):
            search_type = self.combo_search_type_relations.currentText()
            
        rels = self.db_mgr.get_all_relations(search_text, search_type)
        
        for r in rels:
            relation_desc = f"{r['src_table_name']} ➔ {r['ref_table_name']}"
            m_type = r['mapping_type']
            if m_type == "마스터테이블":
                m_type = None
            display_text = f"{relation_desc} ({m_type})" if m_type else relation_desc
            
            item = QListWidgetItem(self.list_relations)
            item.setText(display_text)
            item.setData(Qt.ItemDataRole.UserRole, relation_desc)
            item.setSizeHint(QSize(100, 32))
            self.list_relations.addItem(item)
            
        self.list_relations.setUpdatesEnabled(True)

