    def save_tree_structure_to_db(self):
        table_updates = []
        
        def traverse(item, current_path_parts, order_idx):
            child_count = item.childCount() if item else self.tree_tasks.topLevelItemCount()
            for i in range(child_count):
                child_item = item.child(i) if item else self.tree_tasks.topLevelItem(i)
                data = child_item.data(0, Qt.ItemDataRole.UserRole)
                if not data:
                    continue
                
                if data["type"] == "category":
                    new_parts = current_path_parts + [data["name"]]
                    order_idx = traverse(child_item, new_parts, order_idx)
                elif data["type"] == "table":
                    cat_path = "/".join(current_path_parts) if current_path_parts else "기타"
                    table_updates.append((
                        data["table_name"], 
                        cat_path, 
                        order_idx,
                        data.get("display_name"),
                        data.get("joins_json")
                    ))
                    order_idx += 1
            return order_idx

        traverse(None, [], 0)
        self.db_mgr.save_table_tree_order_and_categories(table_updates)
        self.load_tasks_tree()

    def show_task_tree_context_menu(self, position):
        item = self.tree_tasks.itemAt(position)
        selected_items = self.tree_tasks.selectedItems()
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #FFFFFF;
                border: 1px solid #CBD5E1;
                border-radius: 6px;
                padding: 4px 0px;
            }
            QMenu::item {
                padding: 6px 20px;
                font-size: 11px;
                color: #334155;
            }
            QMenu::item:selected {
                background-color: #EFF6FF;
                color: #2563EB;
                font-weight: bold;
            }
        """)

        all_tables = self.db_mgr.get_all_tables_for_mapping()

        # --- 다중선택 테이블 일괄 제외 ---
        table_items = [it for it in selected_items
                       if it.data(0, Qt.ItemDataRole.UserRole) and
                          it.data(0, Qt.ItemDataRole.UserRole).get("type") == "table"]
        if len(table_items) >= 2:
            act_bulk_remove = menu.addAction(f"❌ 선택한 테이블 {len(table_items)}개 분류에서 제외")
            action = menu.exec(self.tree_tasks.viewport().mapToGlobal(position))
            if action == act_bulk_remove:
                self.bulk_remove_tables_from_category(table_items)
            return

        if item is None:
            # Clicked on empty space
            act_add_cat = menu.addAction("➕ 신규 분류 추가")
            action = menu.exec(self.tree_tasks.viewport().mapToGlobal(position))
            if action == act_add_cat:
                self.add_new_task_category(all_tables)
            return

        data = item.data(0, Qt.ItemDataRole.UserRole)
        if not data:
            return

        if data["type"] == "category":
            cat_path = data["full_path"]

            act_edit_cat = menu.addAction("✏️ 분류명 수정")
            act_delete_cat = menu.addAction("❌ 분류 삭제")
            menu.addSeparator()
            act_add_tables = menu.addAction("➕ 이 분류에 테이블 추가")
            act_add_sub = menu.addAction("➕ 하위 분류 추가")

            action = menu.exec(self.tree_tasks.viewport().mapToGlobal(position))

            if action == act_edit_cat:
                self.rename_task_category_flow(cat_path)
            elif action == act_delete_cat:
                self.delete_task_category_flow(cat_path)
            elif action == act_add_tables:
                self.manage_tables_in_category_flow(cat_path, all_tables)
            elif action == act_add_sub:
                self.add_new_task_subcategory(cat_path)

        elif data["type"] == "table":
            table_name = data["table_name"]
            category_path = data.get("category_path", "기타")
            record_id = data.get("id")

            act_rename_item = menu.addAction("✏️ 이름 변경")
            act_move_cat = menu.addAction("🔄 다른 분류로 이동")
            act_add_cat = menu.addAction("➕ 다른 분류에 추가 등록 (중복 허용)")
            act_remove_cat = menu.addAction("❌ 이 분류에서 제외")

            action = menu.exec(self.tree_tasks.viewport().mapToGlobal(position))

            if action == act_rename_item:
                if record_id:
                    new_name, ok = QInputDialog.getText(
                        self, "이름 변경", 
                        "표시할 이름을 입력하세요:",
                        QLineEdit.EchoMode.Normal,
                        data.get("display_name") or table_name
                    )
                    if ok and new_name.strip():
                        self.db_mgr.update_task_item_display_name(record_id, new_name.strip())
                        self.load_tasks_tree()
                        QMessageBox.information(self, "완료", f"이름이 '{new_name.strip()}'(으)로 변경되었습니다.")
            elif action == act_move_cat:
                if record_id:
                    cats = self.db_mgr.get_unique_categories()
                    if "기타" not in cats:
                        cats.append("기타")
                    chosen_cat, ok = QInputDialog.getItem(
                        self, "분류 이동", 
                        f"'{data.get('display_name') or table_name}' 테이블을 이동할 분류를 선택하거나 입력하세요:", 
                        cats, 0, True
                    )
                    if ok and chosen_cat.strip():
                        self.db_mgr.update_table_category_by_id(record_id, chosen_cat.strip())
                        self.load_tasks_tree()
                        QMessageBox.information(self, "완료", f"이동 완료되었습니다.")
                else:
                    self.move_table_category_flow(table_name, category_path)
            elif action == act_add_cat:
                if record_id:
                    cats = self.db_mgr.get_unique_categories()
                    if "기타" not in cats:
                        cats.append("기타")
                    chosen_cat, ok = QInputDialog.getItem(
                        self, "분류 복사", 
                        f"'{data.get('display_name') or table_name}' 테이블을 추가 등록할 분류를 선택하거나 입력하세요:", 
                        cats, 0, True
                    )
                    if ok and chosen_cat.strip():
                        self.db_mgr.duplicate_table_category_by_id(record_id, chosen_cat.strip())
                        self.load_tasks_tree()
                        QMessageBox.information(self, "완료", f"추가 매핑 완료되었습니다.")
                else:
                    self.add_table_to_additional_category_flow(table_name)
            elif action == act_remove_cat:
                if record_id:
                    res = QMessageBox.question(
                        self, "제외 확인",
                        f"'{data.get('display_name') or table_name}' 테이블을 이 분류에서 제외하시겠습니까?",
                        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                    )
                    if res == QMessageBox.StandardButton.Yes:
                        self.db_mgr.remove_table_category_by_id(record_id)
                        self.load_tasks_tree()
                        QMessageBox.information(self, "완료", f"제외 완료되었습니다.")
                else:
                    self.remove_table_from_category_flow(table_name, category_path)

    def bulk_remove_tables_from_category(self, table_items):
        """업무별 트리에서 선택된 테이블 여러 개를 한꺼번에 분류에서 제외"""
        names = []
        for it in table_items:
            data = it.data(0, Qt.ItemDataRole.UserRole)
            names.append(f"{data['table_name']} ({data.get('category_path', '기타')}분류)")
        preview = "\n".join(names[:10])
        if len(names) > 10:
            preview += f"\n... 외 {len(names)-10}건"
        res = QMessageBox.question(
            self, "일괄 제외 확인",
            f"선택한 {len(table_items)}개의 테이블을 각 분류에서 제외하겠습니까?\n\n{preview}",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if res != QMessageBox.StandardButton.Yes:
            return
        for it in table_items:
            data = it.data(0, Qt.ItemDataRole.UserRole)
            record_id = data.get("id")
            if record_id:
                self.db_mgr.remove_table_category_by_id(record_id)
            else:
                self.db_mgr.remove_table_from_category(
                    data["table_name"], data.get("category_path", "기타")
                )
        self.load_tasks_tree()
        QMessageBox.information(self, "완료", f"{len(table_items)}개의 테이블을 분류에서 제외했습니다.")

    def add_new_task_category(self, all_tables):
        dialog = CategoryAddEditDialog("", self, show_top_level_option=True)
        dialog.setWindowTitle("신규 분류 추가")
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        cat_name = dialog.get_name()
        if not cat_name:
            return

        # 현재 선택된 아이템에서 부모 경로 추출
        item = self.tree_tasks.currentItem()
        parent_path = None
        if item and not dialog.is_top_level():
            data = item.data(0, Qt.ItemDataRole.UserRole)
            if data:
                parent_path = data.get("full_path") or data.get("category_path")
                if data.get("type") == "table":
                    parent_path = data.get("category_path")

        if parent_path and not dialog.is_top_level():
            new_path = f"{parent_path}/{cat_name}"
        else:
            new_path = cat_name

        dlg = TableSelectionDialog(all_tables, [], self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            selected_tables = dlg.get_selected_tables()
            for t_name in selected_tables:
                self.db_mgr.update_table_category(t_name, new_path)
            self.load_tasks_tree()
            QMessageBox.information(self, "완료", f"'{new_path}' 분류를 생성하고 {len(selected_tables)}개의 테이블을 매핑했습니다.")


    def add_new_task_subcategory(self, parent_path):
        sub_name, ok = QInputDialog.getText(self, "하위 분류 추가", f"'{parent_path}' 하위에 추가할 신규 분류명을 입력하세요:")
        if ok and sub_name.strip():
            sub_name = sub_name.strip()
            new_path = f"{parent_path}/{sub_name}"
            all_tables = self.db_mgr.get_all_tables_for_mapping()
            dlg = TableSelectionDialog(all_tables, [], self)
            if dlg.exec() == QDialog.DialogCode.Accepted:
                selected_tables = dlg.get_selected_tables()
                for t_name in selected_tables:
                    self.db_mgr.update_table_category(t_name, new_path)
                self.load_tasks_tree()
                QMessageBox.information(self, "완료", f"'{new_path}' 하위 분류를 생성하고 {len(selected_tables)}개의 테이블을 매핑했습니다.")

    def rename_task_category_flow(self, old_path):
        new_name, ok = QInputDialog.getText(self, "분류명 수정", f"'{old_path}'의 새 분류명을 입력하세요:", text=old_path.split('/')[-1])
        if ok and new_name.strip():
            new_name = new_name.strip()
            parts = old_path.split('/')
            parts[-1] = new_name
            new_path = "/".join(parts)
            self.db_mgr.rename_task_category(old_path, new_path)
            self.load_tasks_tree()
            QMessageBox.information(self, "완료", "분류명이 성공적으로 변경되었습니다.")

    def delete_task_category_flow(self, cat_path):
        reply = QMessageBox.question(
            self, "분류 삭제", 
            f"'{cat_path}' 분류와 하위 분류들을 정말 삭제하시겠습니까?\n분류에 속한 테이블들은 다른 분류가 없는 경우 '기타' 분류로 자동 이동합니다.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if reply == QMessageBox.StandardButton.Yes:
            self.db_mgr.delete_task_category(cat_path)
            self.load_tasks_tree()
            QMessageBox.information(self, "완료", f"'{cat_path}' 분류가 삭제되었습니다.")

    def manage_tables_in_category_flow(self, cat_path, all_tables):
        current_tables = []
        for t in self.db_mgr.get_tables_for_tree():
            if t['task_category'] == cat_path:
                current_tables.append(t['table_name'])
                
        dlg = TableSelectionDialog(all_tables, current_tables, self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            selected_tables = dlg.get_selected_tables()
            
            for t_name in selected_tables:
                self.db_mgr.update_table_category(t_name, cat_path)
                
            for t_name in current_tables:
                if t_name not in selected_tables:
                    self.db_mgr.remove_table_from_category(t_name, cat_path)
                    
            self.load_tasks_tree()
            QMessageBox.information(self, "완료", f"'{cat_path}' 분류의 테이블 구성 변경이 적용되었습니다.")

    def move_table_category_flow(self, table_name, old_category):
        cats = self.db_mgr.get_unique_categories()
        if "기타" not in cats:
            cats.append("기타")
        
        chosen_cat, ok = QInputDialog.getItem(
            self, "분류 이동", 
            f"'{table_name}' 테이블을 이동할 분류를 선택하거나 입력하세요:", 
            cats, 0, True
        )
        if ok and chosen_cat.strip():
            chosen_cat = chosen_cat.strip()
            self.db_mgr.update_table_category(table_name, chosen_cat, old_category)
            self.load_tasks_tree()
            QMessageBox.information(self, "완료", f"'{table_name}' 테이블이 '{chosen_cat}' 분류로 이동되었습니다.")

    def add_table_to_additional_category_flow(self, table_name):
        cats = self.db_mgr.get_unique_categories()
        if "기타" not in cats:
            cats.append("기타")
            
        chosen_cat, ok = QInputDialog.getItem(
            self, "분류 추가", 
            f"'{table_name}' 테이블을 추가 등록할 분류를 선택하거나 입력하세요:", 
            cats, 0, True
        )
        if ok and chosen_cat.strip():
            chosen_cat = chosen_cat.strip()
            self.db_mgr.update_table_category(table_name, chosen_cat)
            self.load_tasks_tree()
            QMessageBox.information(self, "완료", f"'{table_name}' 테이블이 '{chosen_cat}' 분류에 추가 매핑되었습니다.")

    def remove_table_from_category_flow(self, table_name, category_path):
        self.db_mgr.remove_table_from_category(table_name, category_path)
        self.load_tasks_tree()
        QMessageBox.information(self, "완료", f"'{table_name}' 테이블이 '{category_path}' 분류에서 제외되었습니다.")

    # --- 테이블 로딩 및 검색 ---
    def load_tables_list(self, search_text=None, force_reload=False):
        search_type = "테이블"
        if hasattr(self, 'combo_search_type'):
            search_type = self.combo_search_type.currentText()
            
        self.all_tables = self.db_mgr.get_tables_list(search_text, search_type)
        self.loaded_table_count = 0
        
        self.list_tables.setUpdatesEnabled(False)
        self.list_tables.clear()
        self.list_tables.setUpdatesEnabled(True)
        
        self.load_more_tables()

    def load_more_tables(self):
        if not hasattr(self, 'all_tables') or not self.all_tables:
            return
            
        total = len(self.all_tables)
        if self.loaded_table_count >= total:
            return
            
        next_count = min(self.loaded_table_count + 100, total)
        chunk = self.all_tables[self.loaded_table_count:next_count]
        
        search_text = self.txt_search.text() if hasattr(self, 'txt_search') else ""
        self.list_tables.setUpdatesEnabled(False)
        for t in chunk:
            item = QListWidgetItem(self.list_tables)
            custom_widget = TableListWidgetItem(t['table_name'], t['table_ko_name'], t['is_favorite'], search_text)
            custom_widget.favorite_toggled.connect(self.on_favorite_toggled)
            
            item.setSizeHint(QSize(100, 32))
            self.list_tables.addItem(item)
            self.list_tables.setItemWidget(item, custom_widget)
            
        self.loaded_table_count = next_count
        self.list_tables.setUpdatesEnabled(True)

    def on_tables_scroll(self, value):
        scroll_bar = self.list_tables.verticalScrollBar()
        if value >= scroll_bar.maximum() - 10:
            self.load_more_tables()

    def on_favorite_toggled(self, table_name):
        # 1. DB 즐겨찾기 상태 토글 업데이트 (1ms 미만)
        self.db_mgr.toggle_favorite(table_name)
        
        # 2. 현재 검색어/타입 기준 전체 테이블 목록 재조회
        search_text = self.txt_search.text()
        search_type = "테이블"
        if hasattr(self, 'combo_search_type'):
            search_type = self.combo_search_type.currentText()
        self.all_tables = self.db_mgr.get_tables_list(search_text, search_type)
        
        # 3. 스크롤바 위치 사전에 저장
        scroll_bar = self.list_tables.verticalScrollBar()
        scroll_val = scroll_bar.value()
        
        # 4. 현재까지 로딩된 개수 유지하며 다시 리빌드
        current_loaded = self.loaded_table_count
        self.list_tables.setUpdatesEnabled(False)
        scroll_bar.blockSignals(True)
        self.list_tables.clear()
        
        self.loaded_table_count = 0
        total = len(self.all_tables)
        limit = min(current_loaded, total)
        
        # 5. 첫 100개부터 현재 로딩되었던 개수까지 채워서 빌드
        chunk = self.all_tables[0:limit]
        for t in chunk:
            item = QListWidgetItem(self.list_tables)
            custom_widget = TableListWidgetItem(t['table_name'], t['table_ko_name'], t['is_favorite'], search_text)
            custom_widget.favorite_toggled.connect(self.on_favorite_toggled)
            
            item.setSizeHint(QSize(100, 32))
            self.list_tables.addItem(item)
            self.list_tables.setItemWidget(item, custom_widget)
            
        self.loaded_table_count = limit
        
        # 6. 스크롤바 복원 및 업데이트 허용
        scroll_bar.setValue(scroll_val)
        scroll_bar.blockSignals(False)
        self.list_tables.setUpdatesEnabled(True)

    def on_search_changed(self, text):
        self.search_timer.start(250) # 250ms 디바운스

    def on_search_type_changed(self, index):
        stype = self.combo_search_type.currentText()
        if stype == "테이블":
            self.txt_search.setPlaceholderText("테이블명, 한글명 검색...")
        else:
            self.txt_search.setPlaceholderText("컬럼명, 한글명 검색...")
        self.do_search() # 즉시 검색 실행

    def do_search(self):
        self.load_tables_list(self.txt_search.text())

    def clear_search_tables(self):
        self.txt_search.clear()
        self.do_search()

    def clear_search_tasks(self):
        self.txt_search_tasks.clear()
        self.do_task_search()

    def clear_search_codes(self):
        self.txt_search_codes.clear()
        self.do_code_search()

    def clear_search_relations(self):
        self.txt_search_relations.clear()
        self.do_relation_search()

    def on_table_clicked(self, item):
        widget = self.list_tables.itemWidget(item)
        if isinstance(widget, TableListWidgetItem):
            self.open_table_tab(widget.table_name, widget.table_ko_name)

    def on_table_double_clicked(self, item):
        widget = self.list_tables.itemWidget(item)
        if isinstance(widget, TableListWidgetItem):
            self.open_table_tab(widget.table_name, widget.table_ko_name)

    def on_sidebar_relation_clicked(self, item):
        rel_desc = item.data(Qt.ItemDataRole.UserRole)
        if rel_desc:
            tab = self.open_all_relations_tab()
            if tab:
                src_table = rel_desc.split(" ➔ ")[0].strip()
                tab.set_filter(src_table)

    def on_relation_item_double_clicked(self, item):
        rel_desc = item.data(Qt.ItemDataRole.UserRole)
        if rel_desc:
            from PyQt6.QtWidgets import QApplication
            QApplication.clipboard().setText(rel_desc)
            show_copy_message(f"📋 {rel_desc} (이)가 클립보드에 복사되었습니다!", self)

    # --- 우측 메인 영역 탭 제어 로직 ---
    def open_table_tab(self, table_name, table_ko_name=None, joins_json=None, display_name=None):
        self.db_mgr.add_recent_table(table_name)
        self.load_recent_tables_list()

        # 시작 페이지가 열려있다면 안전하게 닫기
        for idx in range(self.tab_widget.count()):
            if self.tab_widget.tabText(idx) == "시작 페이지":
                self.tab_widget.removeTab(idx)
                break

        for idx in range(self.tab_widget.count()):
            tab_widget = self.tab_widget.widget(idx)
            if tab_widget.__class__.__name__ == "TableDetailWidget":
                if hasattr(tab_widget, 'table_name') and tab_widget.table_name:
                    if tab_widget.table_name.strip().upper() == table_name.strip().upper():
                        existing_joins = getattr(tab_widget, 'joins_json', None)
                        existing_display = getattr(tab_widget, 'display_name', None)
                        if existing_joins == joins_json and existing_display == display_name:
                            self.tab_widget.setCurrentIndex(idx)
                            return

        if not table_ko_name:
            with self.db_mgr.get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("SELECT table_ko_name FROM tables WHERE table_name = ?", (table_name,))
                row = cursor.fetchone()
                table_ko_name = row['table_ko_name'] if row else ""

        detail_view = TableDetailWidget(table_name, table_ko_name, self.db_mgr, joins_json=joins_json, display_name=display_name)
        detail_view.link_clicked.connect(self.open_table_tab)
        
        # 💡 관계 편집 발생 시 메인 리스트(관계 사이드바, 전체 관계 탭) 갱신 연동
        detail_view.relation_changed.connect(self.refresh_all_lists_after_edit)
        
        tab_title = display_name if display_name else (table_ko_name if table_ko_name else table_name)
        if joins_json:
            tab_title = f"🔗 {tab_title}"
        new_idx = self.tab_widget.addTab(detail_view, tab_title)
        self.tab_widget.setCurrentIndex(new_idx)

    def refresh_all_lists_after_edit(self):
        """직접 수동으로 관계를 추가/수정/삭제했을 때 목록 실시간 갱신"""
        self.load_relations_list(self.txt_search_relations.text())
        
        # 열려있는 탭 중 AllRelationsTab이나 AllCommonCodesTab이 있으면 리로드
        for idx in range(self.tab_widget.count()):
            tab_w = self.tab_widget.widget(idx)
            if isinstance(tab_w, AllRelationsTab):
                tab_w.load_data()

    def open_all_common_codes_tab(self):
        # 시작 페이지가 열려있다면 안전하게 닫기
        for idx in range(self.tab_widget.count()):
            if self.tab_widget.tabText(idx) == "시작 페이지":
                self.tab_widget.removeTab(idx)
                break

        for idx in range(self.tab_widget.count()):
            tab_widget = self.tab_widget.widget(idx)
            if isinstance(tab_widget, AllCommonCodesTab):
                self.tab_widget.setCurrentIndex(idx)
                return tab_widget

        all_codes_view = AllCommonCodesTab(self.db_mgr)
        new_idx = self.tab_widget.addTab(all_codes_view, "🗂️ 전체 공통코드 명세")
        self.tab_widget.setCurrentIndex(new_idx)

        # 탭 영역 너비가 충분하지 않으면 splitter 자동 확장
        total_w = self.body_splitter.width()
        sizes = self.body_splitter.sizes()
        if len(sizes) == 2:
            sidebar_w = sizes[0]
            tab_w = sizes[1]
            if tab_w < 800:
                new_sidebar = min(sidebar_w, total_w - 820)
                new_sidebar = max(new_sidebar, 200)
                self.body_splitter.setSizes([new_sidebar, total_w - new_sidebar])

        return all_codes_view

    def open_all_relations_tab(self):
        # 시작 페이지가 열려있다면 안전하게 닫기
        for idx in range(self.tab_widget.count()):
            if self.tab_widget.tabText(idx) == "시작 페이지":
                self.tab_widget.removeTab(idx)
                break

        for idx in range(self.tab_widget.count()):
            tab_widget = self.tab_widget.widget(idx)
            if isinstance(tab_widget, AllRelationsTab):
                self.tab_widget.setCurrentIndex(idx)
                return tab_widget

        all_rels_view = AllRelationsTab(self.db_mgr)
        all_rels_view.table_link_clicked.connect(self.open_table_tab)
        
        new_idx = self.tab_widget.addTab(all_rels_view, "🔗 전체 테이블 관계 명세")
        self.tab_widget.setCurrentIndex(new_idx)
        return all_rels_view

    def on_export_spec_clicked(self):
        """테이블 명세서 Excel 내보내기 다이얼로그 열기"""
        dlg = SpecExportDialog(self.db_mgr, self)
        dlg.exec()

    def confirm_close_tab(self, index):
        widget = self.tab_widget.widget(index)
        if hasattr(widget, 'is_dirty') and widget.is_dirty:
            # Set focus to the tab
            self.tab_widget.setCurrentIndex(index)
            
            # Prompt
            msg_box = QMessageBox(self)
            msg_box.setWindowTitle("저장되지 않은 변경사항")
            msg_box.setText(f"'{self.tab_widget.tabText(index).replace('*', '').replace('📄', '').strip()}' 탭의 내용이 변경되었습니다.\n변경사항을 저장하시겠습니까?")
            msg_box.setIcon(QMessageBox.Icon.Question)
            
            btn_save = msg_box.addButton("저장(&Y)", QMessageBox.ButtonRole.AcceptRole)
            btn_discard = msg_box.addButton("저장 안 함(&N)", QMessageBox.ButtonRole.DestructiveRole)
            btn_cancel = msg_box.addButton("취소", QMessageBox.ButtonRole.RejectRole)
            
            # 단축키 Y, N 추가 (Alt 없이 직접 입력 가능)
            shortcut_y = QShortcut(QKeySequence("Y"), msg_box)
            shortcut_y.activated.connect(btn_save.click)
            shortcut_n = QShortcut(QKeySequence("N"), msg_box)
            shortcut_n.activated.connect(btn_discard.click)
            
            msg_box.setDefaultButton(btn_save)
            msg_box.exec()
            
            clicked_button = msg_box.clickedButton()
            if clicked_button == btn_save:
                if hasattr(widget, 'save_task'):
                    widget.save_task()
                elif hasattr(widget, 'on_save_clicked'):
                    widget.on_save_clicked()
                
                # If still dirty, save failed or cancelled
                return not widget.is_dirty
            elif clicked_button == btn_discard:
                if hasattr(widget, 'discard_changes'):
                    widget.discard_changes()
                return True
            else:
                return False
        return True

    def close_tab(self, index):
        tab_text = self.tab_widget.tabText(index)
        if tab_text in ["시작 페이지"]:
            return False  # 고정 페이지는 닫기 방지

        if not self.confirm_close_tab(index):
            return False

        widget = self.tab_widget.widget(index)
        for k, v in list(self.open_query_tabs.items()):
            if v == widget:
                del self.open_query_tabs[k]
                break

        for k, v in list(self.open_task_tabs.items()):
            if v == widget:
                del self.open_task_tabs[k]
                break

        self.tab_widget.removeTab(index)
        if self.tab_widget.count() == 0:
            self.tab_widget.addTab(self.welcome_widget, "시작 페이지")
            self.tab_widget.tabBar().setTabButton(0, QTabBar.ButtonPosition.RightSide, None)
        return True

    def on_tab_bar_context_menu(self, point):
        index = self.tab_widget.tabBar().tabAt(point)
        if index < 0:
            return
        
        target_widget = self.tab_widget.widget(index)
        tab_text = self.tab_widget.tabText(index)
        if tab_text == "시작 페이지":
            return

        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #FFFFFF;
                border: 1px solid #CBD5E1;
                border-radius: 6px;
                padding: 4px 0px;
            }
            QMenu::item {
                padding: 6px 16px;
                font-size: 12px;
                color: #334155;
            }
            QMenu::item:selected {
                background-color: #F1F5F9;
                color: #2563EB;
            }
        """)

        # 1. 이 탭 닫기
        action_close_this = QAction("이 탭 닫기", self)
        action_close_this.triggered.connect(lambda checked=False, idx=index: self.close_tab(idx))
        menu.addAction(action_close_this)

        # 2. 이 탭 제외 모두 닫기
        action_close_others = QAction("이 탭 제외 모두 닫기", self)
        action_close_others.triggered.connect(lambda checked=False, idx=index: self.close_other_tabs(idx))
        menu.addAction(action_close_others)

        # 3. 해당 유형 탭 외에 모두 닫기
        target_type = target_widget.__class__
        action_close_type_others = QAction("해당 유형 탭 외에 모두 닫기", self)
        action_close_type_others.triggered.connect(lambda checked=False, t_type=target_type: self.close_other_type_tabs(t_type))
        menu.addAction(action_close_type_others)

        # 4. 모든 탭 닫기
        action_close_all = QAction("모든 탭 닫기", self)
        action_close_all.triggered.connect(self.close_all_tabs)
        menu.addAction(action_close_all)

        menu.exec(self.tab_widget.tabBar().mapToGlobal(point))

    def close_all_tabs(self):
        for idx in range(self.tab_widget.count() - 1, -1, -1):
            tab_text = self.tab_widget.tabText(idx)
            if tab_text != "시작 페이지":
                if not self.close_tab(idx):
                    break

    def close_other_tabs(self, keep_index):
        keep_widget = self.tab_widget.widget(keep_index)
        for idx in range(self.tab_widget.count() - 1, -1, -1):
            if self.tab_widget.widget(idx) != keep_widget:
                tab_text = self.tab_widget.tabText(idx)
                if tab_text != "시작 페이지":
                    if not self.close_tab(idx):
                        break

    def close_other_type_tabs(self, target_type):
        for idx in range(self.tab_widget.count() - 1, -1, -1):
            w = self.tab_widget.widget(idx)
            tab_text = self.tab_widget.tabText(idx)
            if tab_text != "시작 페이지":
                if not isinstance(w, target_type):
                    if not self.close_tab(idx):
                        break

